window.CGL_DATA=window.CGL_DATA||{};window.CGL_DATA["CGL-14-OCT-2026-SHIFT-3"]={"id":"CGL-14-OCT-2026-SHIFT-3","title":"CGL 14 OCT 2026 SHIFT 3","order":["REASONING","GK","MATH","ENGLISH"],"marking":{"correct":2,"negative":0.5},"qualifying":[],"sections":{"REASONING":{"seconds":900,"questions":[{"no":1,"local_id":"50001","quid":"Q1000072481","section":"REASONING","topic":"Statement & Conclusion","question":{"en":"Read the following statement carefully and identify the conclusion that follows.<br><br><b>Statement:</b> Majority of the population now prefers digital payments over cash.<br><b>Conclusions:</b><br>I. Cash transactions are becoming obsolete.<br>II. Technology adoption has increased significantly. [SSC CGL 14/10/26 Shift 3]","hi":"निम्नलिखित कथन को ध्यान से पढ़िए और वह निष्कर्ष पहचानिए जो अनुसरण करता है।<br><br><b>कथन:</b> अब अधिकांश जनसंख्या नकद के बजाय डिजिटल भुगतान पसंद करती है।<br><b>निष्कर्ष:</b><br>I. नकद लेन-देन अप्रचलित हो रहे हैं।<br>II. प्रौद्योगिकी का उपयोग उल्लेखनीय रूप से बढ़ा है। [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Only Conclusion I follows","hi":"केवल निष्कर्ष I अनुसरण करता है"},"2":{"en":"Only Conclusion II follows","hi":"केवल निष्कर्ष II अनुसरण करता है"},"3":{"en":"Both I and II follow","hi":"I और II दोनों अनुसरण करते हैं"},"4":{"en":"Neither I nor II follows","hi":"न तो I और न ही II अनुसरण करता है"}},"answer":"2","solution":{"en":"A shift of the majority towards digital payments shows that people have adopted the technology widely, so II follows<br>It does not mean that cash has stopped being used or has become obsolete, so I does not follow<br>Hence only conclusion II follows<br><br><b>Hence, the correct answer is option (2): Only Conclusion II follows.</b>","hi":"अधिकांश लोगों का डिजिटल भुगतान की ओर झुकाव दर्शाता है कि लोगों ने इस तकनीक को व्यापक रूप से अपनाया है, अतः II अनुसरण करता है<br>इसका अर्थ यह नहीं कि नकद का उपयोग बंद हो गया या वह अप्रचलित हो गया, अतः I अनुसरण नहीं करता<br>इसलिए केवल निष्कर्ष II अनुसरण करता है<br><br><b>अतः सही उत्तर विकल्प (2): केवल निष्कर्ष II अनुसरण करता है है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":2,"local_id":"50002","quid":"Q1000072482","section":"REASONING","topic":"Number Series","question":{"en":"Every morning, the temperature rose in the below sequence. Find next.<br>15°C, 17°C, 19°C, 21°C, ? [SSC CGL 14/10/26 Shift 3]","hi":"प्रत्येक सुबह तापमान नीचे दिए क्रम में बढ़ा। अगला मान ज्ञात कीजिए।<br>15°C, 17°C, 19°C, 21°C, ? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"23°C"},"2":{"en":"22°C"},"3":{"en":"25°C"},"4":{"en":"27°C"}},"answer":"1","solution":{"en":"Every term is 2°C more than the previous one: 15, 17, 19, 21<br>Next term = 21 + 2 = 23°C<br><br><b>Hence, the correct answer is option (1): 23°C.</b>","hi":"प्रत्येक पद पिछले पद से 2°C अधिक है: 15, 17, 19, 21<br>अगला पद = 21 + 2 = 23°C<br><br><b>अतः सही उत्तर विकल्प (1): 23°C है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":3,"local_id":"50003","quid":"Q1000072483","section":"REASONING","topic":"Coding & Decoding","question":{"en":"If \"KING\" = \"11 9 14 7\", how is \"QUEEN\" coded? [SSC CGL 14/10/26 Shift 3]","hi":"यदि \"KING\" = \"11 9 14 7\" है, तो \"QUEEN\" का कूट क्या होगा? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"17 21 5 5 14"},"2":{"en":"16 22 4 6 13"},"3":{"en":"18 23 3 7 12"},"4":{"en":"19 24 2 8 11"}},"answer":"1","solution":{"en":"Every letter is replaced by its alphabet position: K = 11, I = 9, N = 14, G = 7<br>QUEEN gives Q = 17, U = 21, E = 5, E = 5, N = 14<br>Code = 17 21 5 5 14<br><br><b>Hence, the correct answer is option (1): 17 21 5 5 14.</b>","hi":"प्रत्येक अक्षर को उसके वर्णमाला क्रम से बदला जाता है: K = 11, I = 9, N = 14, G = 7<br>QUEEN = Q = 17, U = 21, E = 5, E = 5, N = 14<br>कूट = 17 21 5 5 14<br><br><b>अतः सही उत्तर विकल्प (1): 17 21 5 5 14 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":4,"local_id":"50004","quid":"Q1000072484","section":"REASONING","topic":"Venn Diagrams","question":{"en":"In a survey, 70 people liked cricket, 60 liked football, and 30 liked both. How many liked only football? [SSC CGL 14/10/26 Shift 3]","hi":"एक सर्वेक्षण में 70 लोगों को क्रिकेट, 60 को फुटबॉल और 30 को दोनों पसंद थे। कितनों को केवल फुटबॉल पसंद था? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"30"},"2":{"en":"20"},"3":{"en":"10"},"4":{"en":"25"}},"answer":"1","solution":{"en":"Only football = Football − both = 60 − 30 = 30<br><br><b>Hence, the correct answer is option (1): 30.</b>","hi":"केवल फुटबॉल = फुटबॉल − दोनों = 60 − 30 = 30<br><br><b>अतः सही उत्तर विकल्प (1): 30 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":5,"local_id":"50005","quid":"Q1000072485","section":"REASONING","topic":"Venn Diagrams","question":{"en":"Among 300 students, 180 like English, 150 like Hindi, 120 like both. How many like exactly one language? [SSC CGL 14/10/26 Shift 3]","hi":"300 विद्यार्थियों में 180 को अंग्रेज़ी, 150 को हिंदी और 120 को दोनों पसंद हैं। कितनों को ठीक एक भाषा पसंद है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"30"},"2":{"en":"60"},"3":{"en":"90"},"4":{"en":"100"}},"answer":"3","solution":{"en":"Only English = 180 − 120 = 60 and only Hindi = 150 − 120 = 30<br>Exactly one language = 60 + 30 = 90<br><br><b>Hence, the correct answer is option (3): 90.</b>","hi":"केवल अंग्रेज़ी = 180 − 120 = 60 तथा केवल हिंदी = 150 − 120 = 30<br>ठीक एक भाषा = 60 + 30 = 90<br><br><b>अतः सही उत्तर विकल्प (3): 90 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":6,"local_id":"50006","quid":"Q1000072486","section":"REASONING","topic":"Miscellaneous","question":{"en":"A, B, and C together can complete a piece of work in 10 days. A alone can do it in 20 days, and B in 30 days.<br>How many days will C alone take to complete the work? [SSC CGL 14/10/26 Shift 3]","hi":"A, B और C मिलकर एक कार्य 10 दिनों में पूरा कर सकते हैं। A अकेला उसे 20 दिनों में और B 30 दिनों में कर सकता है।<br>C अकेला वह कार्य कितने दिनों में पूरा करेगा? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"40"},"2":{"en":"60"},"3":{"en":"50"},"4":{"en":"45"}},"answer":"2","solution":{"en":"Work done by all three in one day = \\(\\frac{1}{10}\\), by A = \\(\\frac{1}{20}\\), by B = \\(\\frac{1}{30}\\)<br>C's one day work = \\(\\frac{1}{10}-\\frac{1}{20}-\\frac{1}{30}=\\frac{6-3-2}{60}=\\frac{1}{60}\\)<br>So C alone takes 60 days<br><br><b>Hence, the correct answer is option (2): 60.</b>","hi":"तीनों का एक दिन का कार्य = \\(\\frac{1}{10}\\), A का = \\(\\frac{1}{20}\\), B का = \\(\\frac{1}{30}\\)<br>C का एक दिन का कार्य = \\(\\frac{1}{10}-\\frac{1}{20}-\\frac{1}{30}=\\frac{6-3-2}{60}=\\frac{1}{60}\\)<br>अतः C अकेला 60 दिन लेगा<br><br><b>अतः सही उत्तर विकल्प (2): 60 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":7,"local_id":"50007","quid":"Q1000072487","section":"REASONING","topic":"Odd One Out","question":{"en":"In this following question, four words have been given, out of which three are alike in some manner and the fourth one is different. Choose odd one out. [SSC CGL 14/10/26 Shift 3]","hi":"निम्नलिखित प्रश्न में चार शब्द दिए गए हैं, जिनमें तीन किसी प्रकार एक जैसे हैं और चौथा भिन्न है। विषम शब्द चुनिए। [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Voltmeter","hi":"वोल्टमीटर"},"2":{"en":"Ammeter","hi":"अमीटर"},"3":{"en":"Galvanometer","hi":"गैल्वेनोमीटर"},"4":{"en":"Microscope","hi":"सूक्ष्मदर्शी"}},"answer":"4","solution":{"en":"Voltmeter, ammeter and galvanometer are all instruments used to measure electrical quantities<br>A microscope is an optical instrument used to see tiny objects, so it is not an electrical measuring device<br>Hence microscope is the odd one<br><br><b>Hence, the correct answer is option (4): Microscope.</b>","hi":"वोल्टमीटर, अमीटर और गैल्वेनोमीटर सभी विद्युत राशियाँ मापने के उपकरण हैं<br>सूक्ष्मदर्शी एक प्रकाशिक उपकरण है जो छोटी वस्तुएँ देखने के लिए प्रयोग होता है, अतः यह विद्युत मापक यंत्र नहीं है<br>इसलिए सूक्ष्मदर्शी विषम है<br><br><b>अतः सही उत्तर विकल्प (4): सूक्ष्मदर्शी है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":8,"local_id":"50008","quid":"Q1000072488","section":"REASONING","topic":"Address/Sentence Matching","question":{"en":"Choose the option that perfectly matches the given address.<br><br><b>Original Address:</b><br>Unit No. 7-C/11The Emperor's Court Residency, Block-VIII Dr. A.P.J. Abdul Kalam Marg New Delhi – 110021India | Asia [SSC CGL 14/10/26 Shift 3]","hi":"वह विकल्प चुनिए जो दिए गए पते से पूर्णतः मेल खाता है।<br><br><b>मूल पता:</b><br>Unit No. 7-C/11The Emperor's Court Residency, Block-VIII Dr. A.P.J. Abdul Kalam Marg New Delhi – 110021India | Asia [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Unit No. 7-C/11The Emperor's Court Residency, Block-VIII Dr. A.P.J. Abdul Kalam Marg New Delhi – 110012India | Asia"},"2":{"en":"Unit No. 7-C/11The Emperor's Court Residency, Block-VII Dr. A.P.J. Abdul Kalam Marg New Delhi – 110021India | Asia"},"3":{"en":"Unit No. 7-C/11The Emperor's Court Residency. Block-VIII Dr. A.P.J. Abdul Kalam Marg New Delhi – 110021India | Asia"},"4":{"en":"Unit No. 7-C/11The Emperor's Court Residency, Block-VIII Dr. A.P.J. Abdul Kalam Marg New Delhi – 110021India | Asia"}},"answer":"4","solution":{"en":"Option 1 changes the PIN to 110012 and option 2 writes Block-VII instead of Block-VIII<br>Option 3 puts a full stop after 'Residency' where the original has a comma<br>Only option 4 repeats every word, punctuation mark and the PIN 110021 exactly<br><br><b>Hence, the correct answer is option (4): Unit No. 7-C/11The Emperor's Court Residency, Block-VIII Dr. A.P.J. Abdul Kalam Marg New Delhi – 110021India | Asia.</b>","hi":"विकल्प 1 में पिन 110012 हो गया है और विकल्प 2 में Block-VIII के स्थान पर Block-VII है<br>विकल्प 3 में 'Residency' के बाद मूल अल्पविराम के स्थान पर पूर्णविराम है<br>केवल विकल्प 4 प्रत्येक शब्द, विराम-चिह्न तथा पिन 110021 ठीक दोहराता है<br><br><b>अतः सही उत्तर विकल्प (4): Unit No. 7-C/11The Emperor's Court Residency, Block-VIII Dr. A.P.J. Abdul Kalam Marg New Delhi – 110021India | Asia है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":9,"local_id":"50009","quid":"Q1000072489","section":"REASONING","topic":"Counting Figures","question":{"en":"How many triangles are there in the given figure?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q9.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]","hi":"दी गई आकृति में कितने त्रिभुज हैं?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q9.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"4","solution":{"en":"The figure is a large right-angled triangle divided by horizontal and vertical lines into small squares which carry diagonals<br>Counting size-wise: 19 small triangles, 8 triangles made of two parts each and 6 large triangles made of four or more parts<br>Total = 19 + 8 + 6 = 33<br><br><b>Hence, the correct answer is option (4): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q9_opt4.jpg\" style=\"max-width:100%;height:auto\">.</b>","hi":"आकृति एक बड़ा समकोण त्रिभुज है जो क्षैतिज और ऊर्ध्वाधर रेखाओं से छोटे वर्गों में बँटा है और इन वर्गों में विकर्ण हैं<br>आकार के अनुसार गिनने पर: 19 छोटे त्रिभुज, दो भागों से बने 8 त्रिभुज तथा चार या अधिक भागों से बने 6 बड़े त्रिभुज<br>कुल = 19 + 8 + 6 = 33<br><br><b>अतः सही उत्तर विकल्प (4): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q9_opt4.jpg\" style=\"max-width:100%;height:auto\"> है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q9.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q9_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q9_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q9_opt3.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q9_opt4.jpg"]},"solution":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q9_opt4.jpg"]}},{"no":10,"local_id":"50010","quid":"Q1000072490","section":"REASONING","topic":"Word Formation & Letter/Word Position","question":{"en":"If in the word LANGUAGE the first and second letters are interchanged, in the same way the third and fourth, fifth and sixth and so on are interchanged, then what will be the 4th letter from the left? [SSC CGL 14/10/26 Shift 3]","hi":"यदि शब्द LANGUAGE में पहले और दूसरे अक्षर को परस्पर बदला जाए, उसी प्रकार तीसरे और चौथे, पाँचवें और छठे आदि को बदला जाए, तो बाईं ओर से चौथा अक्षर क्या होगा? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"G"},"2":{"en":"U"},"3":{"en":"N"},"4":{"en":"A"}},"answer":"3","solution":{"en":"Pairs are swapped: LA → AL, NG → GN, UA → AU, GE → EG<br>New word = ALGN AUEG<br>4th letter from the left = N<br><br><b>Hence, the correct answer is option (3): N.</b>","hi":"युग्म बदलने पर: LA → AL, NG → GN, UA → AU, GE → EG<br>नया शब्द = ALGNAUEG<br>बाईं ओर से चौथा अक्षर = N<br><br><b>अतः सही उत्तर विकल्प (3): N है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":11,"local_id":"50011","quid":"Q1000072491","section":"REASONING","topic":"Letter & Alphanumeric Series","question":{"en":"Study the pattern in the given series and find the next set of letters in the series.<br>BHA, ZIY, XJW, ? [SSC CGL 14/10/26 Shift 3]","hi":"दी गई श्रेणी का पैटर्न अध्ययन कीजिए और अक्षरों का अगला समूह ज्ञात कीजिए।<br>BHA, ZIY, XJW, ? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"VKU"},"2":{"en":"VJU"},"3":{"en":"VKT"},"4":{"en":"VKV"}},"answer":"1","solution":{"en":"First letters B, Z, X go 2 back each time, so next is V<br>Second letters H, I, J go 1 forward, so next is K<br>Third letters A, Y, W go 2 back, so next is U<br>Next group = VKU<br><br><b>Hence, the correct answer is option (1): VKU.</b>","hi":"पहले अक्षर B, Z, X हर बार 2 पीछे, अतः अगला V<br>दूसरे अक्षर H, I, J हर बार 1 आगे, अतः अगला K<br>तीसरे अक्षर A, Y, W हर बार 2 पीछे, अतः अगला U<br>अगला समूह = VKU<br><br><b>अतः सही उत्तर विकल्प (1): VKU है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":12,"local_id":"50012","quid":"Q1000072492","section":"REASONING","topic":"Miscellaneous","question":{"en":"Which of the following centre codes does not follow the pattern where the numeric value equals the sum of the positions of the two letters in the alphabet? [SSC CGL 14/10/26 Shift 3]","hi":"निम्नलिखित में से कौन-सा केंद्र कूट उस पैटर्न का पालन नहीं करता जिसमें संख्यात्मक मान दोनों अक्षरों के वर्णमाला स्थानों के योग के बराबर होता है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"AD5"},"2":{"en":"BE7"},"3":{"en":"CF8"},"4":{"en":"DG11"}},"answer":"3","solution":{"en":"AD5: 1 + 4 = 5 ✔ and BE7: 2 + 5 = 7 ✔<br>CF8: 3 + 6 = 9, not 8 ✘<br>DG11: 4 + 7 = 11 ✔, so CF8 does not follow the pattern<br><br><b>Hence, the correct answer is option (3): CF8.</b>","hi":"AD5: 1 + 4 = 5 ✔ तथा BE7: 2 + 5 = 7 ✔<br>CF8: 3 + 6 = 9 है, 8 नहीं ✘<br>DG11: 4 + 7 = 11 ✔, अतः CF8 पैटर्न का पालन नहीं करता<br><br><b>अतः सही उत्तर विकल्प (3): CF8 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":13,"local_id":"50013","quid":"Q1000072493","section":"REASONING","topic":"Letter/Alphabetical Analogy","question":{"en":"What should come in place of the question mark (?) in the following analogy?<br>ACE : FHJ :: MOQ : ? [SSC CGL 14/10/26 Shift 3]","hi":"निम्नलिखित सादृश्य में प्रश्नवाचक चिह्न (?) के स्थान पर क्या आएगा?<br>ACE : FHJ :: MOQ : ? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"RTV"},"2":{"en":"STV"},"3":{"en":"RTU"},"4":{"en":"SUW"}},"answer":"1","solution":{"en":"Every letter of ACE moves five places forward to give FHJ<br>MOQ gives M→R, O→T, Q→V<br>So the answer is RTV<br><br><b>Hence, the correct answer is option (1): RTV.</b>","hi":"ACE का प्रत्येक अक्षर पाँच स्थान आगे बढ़कर FHJ बनाता है<br>MOQ से M→R, O→T, Q→V<br>अतः उत्तर RTV है<br><br><b>अतः सही उत्तर विकल्प (1): RTV है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":14,"local_id":"50014","quid":"Q1000072494","section":"REASONING","topic":"Figure Completing","question":{"en":"Complete the pattern in fig. (X) by selecting one of the figures from the four alternatives :<br>Figure(X):<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q14.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]","hi":"आकृति (X) का पैटर्न चार विकल्पों में से एक आकृति चुनकर पूरा कीजिए :<br>आकृति (X):<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q14.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"4","solution":{"en":"Figure (X) is a broad arrow pointing down, filled with V-shaped black bands that follow the direction of the arrow, and its middle part is blank<br>The blank part must continue the same nested V bands at the same spacing and with the same thickness<br>Only option 4 repeats these V bands exactly, while the others change their angle or their width<br><br><b>Hence, the correct answer is option (4): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q14_opt4.jpg\" style=\"max-width:100%;height:auto\">.</b>","hi":"आकृति (X) नीचे की ओर इंगित एक चौड़ा तीर है जो तीर की दिशा के अनुसार V आकार की काली पट्टियों से भरा है और इसका मध्य भाग खाली है<br>खाली भाग में उसी अंतराल और उसी मोटाई की V पट्टियाँ जारी रहनी चाहिए<br>केवल विकल्प 4 में ये V पट्टियाँ ठीक वैसी ही हैं, अन्य विकल्प उनका कोण या चौड़ाई बदल देते हैं<br><br><b>अतः सही उत्तर विकल्प (4): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q14_opt4.jpg\" style=\"max-width:100%;height:auto\"> है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q14.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q14_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q14_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q14_opt3.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q14_opt4.jpg"]},"solution":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q14_opt4.jpg"]}},{"no":15,"local_id":"50015","quid":"Q1000072495","section":"REASONING","topic":"Mathematical Operations","question":{"en":"Which of the interchanges of signs will make the given mathematical statement logically correct?<br>54 ÷ 9 − 3 × 4 + 2 = 16 [SSC CGL 14/10/26 Shift 3]","hi":"किन चिह्नों को परस्पर बदलने से दिया गया गणितीय कथन तार्किक रूप से सही हो जाएगा?<br>54 ÷ 9 − 3 × 4 + 2 = 16 [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"+ and ×","hi":"+ और ×"},"2":{"en":"÷ and ×","hi":"÷ और ×"},"3":{"en":"− and +","hi":"− और +"},"4":{"en":"÷ and −","hi":"÷ और −"}},"answer":"3","solution":{"en":"Original: 54 ÷ 9 − 3 × 4 + 2 = 6 − 12 + 2 = −4 ✘<br>Interchanging − and + : 54 ÷ 9 + 3 × 4 − 2 = 6 + 12 − 2 = 16 ✔<br><br><b>Hence, the correct answer is option (3): − and +.</b>","hi":"मूल: 54 ÷ 9 − 3 × 4 + 2 = 6 − 12 + 2 = −4 ✘<br>− और + बदलने पर: 54 ÷ 9 + 3 × 4 − 2 = 6 + 12 − 2 = 16 ✔<br><br><b>अतः सही उत्तर विकल्प (3): − और + है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":16,"local_id":"50016","quid":"Q1000072496","section":"REASONING","topic":"Eligibility","question":{"en":"Read the eligibility criteria given for the post carefully and answer the question that follows.<br><b>Eligibility Criteria for Field Inspector:</b><br>1. Graduate in Science stream.<br>2. Minimum 3 years of work experience in field research.<br>3. Age: Not exceeding 35 years.<br><b>Case:</b> Amit is 32 years old, has a bachelor's degree in physics, and has 4 years of experience in field research. What should be done in Amit's case? [SSC CGL 14/10/26 Shift 3]","hi":"पद के लिए दी गई पात्रता शर्तें ध्यान से पढ़िए और आगे दिए प्रश्न का उत्तर दीजिए।<br><b>क्षेत्र निरीक्षक के लिए पात्रता शर्तें:</b><br>1. विज्ञान संवर्ग में स्नातक।<br>2. क्षेत्र अनुसंधान में न्यूनतम 3 वर्ष का कार्य अनुभव।<br>3. आयु: 35 वर्ष से अधिक नहीं।<br><b>मामला:</b> अमित 32 वर्ष का है, उसके पास भौतिक विज्ञान में स्नातक की डिग्री है और क्षेत्र अनुसंधान में 4 वर्ष का अनुभव है। अमित के मामले में क्या किया जाना चाहिए? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Eligible","hi":"पात्र"},"2":{"en":"Not Eligible (Educational background)","hi":"अपात्र (शैक्षिक पृष्ठभूमि)"},"3":{"en":"Not Eligible (Experience less)","hi":"अपात्र (अनुभव कम)"},"4":{"en":"Not Eligible (Age more)","hi":"अपात्र (आयु अधिक)"}},"answer":"1","solution":{"en":"Physics is a science subject, so the graduation condition is satisfied<br>Experience of 4 years is more than the required 3 years and the age 32 is below 35<br>All three conditions are met, so Amit is eligible<br><br><b>Hence, the correct answer is option (1): Eligible.</b>","hi":"भौतिक विज्ञान विज्ञान विषय है, अतः स्नातक की शर्त पूरी होती है<br>4 वर्ष का अनुभव आवश्यक 3 वर्ष से अधिक है और आयु 32 वर्ष, 35 से कम है<br>तीनों शर्तें पूरी हैं, अतः अमित पात्र है<br><br><b>अतः सही उत्तर विकल्प (1): पात्र है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":17,"local_id":"50017","quid":"Q1000072497","section":"REASONING","topic":"Embedded Figures","question":{"en":"In the following question, a figure (X) is given, followed by four alternative figures (1), (2), (3), and (4) such that figure (X) is embedded in one of them. Trace out the alternative figure that contains fig. (X) as part of it.<br>Figure(X):<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q17.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]","hi":"निम्नलिखित प्रश्न में आकृति (X) दी गई है और उसके बाद चार विकल्प आकृतियाँ (1), (2), (3) और (4) हैं, जिनमें आकृति (X) किसी एक में अंतर्निहित है। वह विकल्प आकृति पहचानिए जिसमें आकृति (X) उसके भाग के रूप में है।<br>आकृति (X):<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q17.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"1","solution":{"en":"Figure (X) is a square whose upper side carries a downward slanting line from the middle and whose lower-left part carries a short slanting line cutting the corner<br>The answer figure must contain this square together with both slanting lines at the same positions<br>Only alternative figure 4 has a square grid that supplies exactly these two slanting lines, so figure (X) is embedded there<br><br><b>Hence, the correct answer is option (1): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q21_opt4.jpg\" style=\"max-width:100%;height:auto\">.</b>","hi":"आकृति (X) एक वर्ग है जिसकी ऊपरी भुजा के मध्य से नीचे की ओर तिरछी रेखा है और निचले-बाएँ भाग में कोना काटती एक छोटी तिरछी रेखा है<br>उत्तर आकृति में यह वर्ग तथा दोनों तिरछी रेखाएँ उसी स्थिति में होनी चाहिए<br>केवल विकल्प आकृति 4 के वर्ग-जाल में ठीक ये दोनों तिरछी रेखाएँ हैं, अतः वहीं आकृति (X) अंतर्निहित है<br><br><b>अतः सही उत्तर विकल्प (1): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q21_opt4.jpg\" style=\"max-width:100%;height:auto\"> है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q17.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q21_opt4.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt1.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q21_opt1.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt2.jpg"]},"solution":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q21_opt4.jpg"]}},{"no":18,"local_id":"50018","quid":"Q1000072498","section":"REASONING","topic":"Statement, Assumption & Argument","question":{"en":"Read the given statement carefully and the following assumptions based on it. Decide which of the assumptions are implicit in the statement.<br><b>Statement:</b><br>Organizations should provide mandatory mental health leave to their employees to foster a supportive and healthy working environment for everyone involved.<br><b>Assumptions:</b><br>I. Employees are currently facing significant levels of stress that affect their performance.<br>II. Offering mental health leave will lead to an overall improvement in the well-being of staff. [SSC CGL 14/10/26 Shift 3]","hi":"दिया गया कथन ध्यान से पढ़िए और उस पर आधारित अनुमानों को देखिए। निर्णय कीजिए कि कौन-से अनुमान कथन में निहित हैं।<br><b>कथन:</b><br>संगठनों को अपने कर्मचारियों को अनिवार्य मानसिक स्वास्थ्य अवकाश देना चाहिए ताकि सभी के लिए सहायक और स्वस्थ कार्य वातावरण बन सके।<br><b>अनुमान:</b><br>I. कर्मचारी इस समय उल्लेखनीय तनाव का सामना कर रहे हैं जो उनके कार्य-निष्पादन को प्रभावित करता है।<br>II. मानसिक स्वास्थ्य अवकाश देने से कर्मचारियों के समग्र कल्याण में सुधार होगा। [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Only Assumption I is implicit","hi":"केवल अनुमान I निहित है"},"2":{"en":"Neither Assumption I nor II is implicit","hi":"न तो अनुमान I और न ही II निहित है"},"3":{"en":"Both Assumptions I and II are implicit","hi":"अनुमान I और II दोनों निहित हैं"},"4":{"en":"Only Assumption II is implicit","hi":"केवल अनुमान II निहित है"}},"answer":"3","solution":{"en":"Such leave is recommended because stress is already affecting the employees, so I is implicit<br>The suggestion also assumes that the leave will improve the well-being of the staff, so II is implicit<br>Hence both assumptions are implicit<br><br><b>Hence, the correct answer is option (3): Both Assumptions I and II are implicit.</b>","hi":"ऐसा अवकाश इसलिए सुझाया गया है क्योंकि तनाव पहले से कर्मचारियों को प्रभावित कर रहा है, अतः I निहित है<br>सुझाव यह भी मानता है कि अवकाश से कर्मचारियों का कल्याण सुधरेगा, अतः II निहित है<br>इसलिए दोनों अनुमान निहित हैं<br><br><b>अतः सही उत्तर विकल्प (3): अनुमान I और II दोनों निहित हैं है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":19,"local_id":"50019","quid":"Q1000072499","section":"REASONING","topic":"Odd One Out","question":{"en":"In the following question, out of the five figures marked (a), (b), (c), (d), and (e), four are similar in a certain manner. However, one figure is not like the other four. Choose the figure which is different from the rest.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q19.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]","hi":"निम्नलिखित प्रश्न में (a), (b), (c), (d) और (e) से अंकित पाँच आकृतियों में से चार किसी प्रकार एक जैसी हैं। परंतु एक आकृति शेष चारों जैसी नहीं है। वह आकृति चुनिए जो शेष से भिन्न है।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q19.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"3","solution":{"en":"In four of the five squares the small dark and white parts stay in the same relative positions, so one figure is only a rotation of the others<br>In option 4 the arrangement of the shaded and dotted parts is reversed instead of being rotated, so it cannot be obtained by turning any of the other figures<br>Hence the figure in option 4 is different from the rest<br><br><b>Hence, the correct answer is option (3): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-13-OCT-2026-SHIFT-3/q19_opt2.jpg\" style=\"max-width:100%;height:auto\">.</b>","hi":"पाँच में से चार वर्गों में छोटे काला और सफ़ेद भाग एक ही सापेक्ष स्थिति में रहते हैं, अतः एक आकृति शेष का केवल घुमाव है<br>विकल्प 4 में छायांकित और बिंदुदार भागों की व्यवस्था घुमाव के बजाय उलट दी गई है, अतः यह किसी भी अन्य आकृति को घुमाकर नहीं प्राप्त की जा सकती<br>इसलिए विकल्प 4 की आकृति शेष से भिन्न है<br><br><b>अतः सही उत्तर विकल्प (3): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-13-OCT-2026-SHIFT-3/q19_opt2.jpg\" style=\"max-width:100%;height:auto\"> है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q19.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-13-OCT-2026-SHIFT-3/q16_opt4.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-13-OCT-2026-SHIFT-3/q16_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-13-OCT-2026-SHIFT-3/q19_opt2.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-13-OCT-2026-SHIFT-3/q16_opt1.jpg"]},"solution":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-13-OCT-2026-SHIFT-3/q19_opt2.jpg"]}},{"no":20,"local_id":"50020","quid":"Q1000072500","section":"REASONING","topic":"Figure Series & Figure Analogy","question":{"en":"In the following question, there is a specific relationship between the first two figures. Establish a similar relationship between the third and fourth figures by selecting a suitable figure from the given Answer Figures to replace the question mark (?).<br><b>Question Figures:</b><br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q20.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]","hi":"निम्नलिखित प्रश्न में पहली दो आकृतियों के बीच एक विशिष्ट संबंध है। तीसरी और चौथी आकृति के बीच भी वही संबंध स्थापित कीजिए और प्रश्नवाचक चिह्न (?) के स्थान पर दी गई उत्तर आकृतियों में से उपयुक्त आकृति चुनिए।<br><b>प्रश्न आकृतियाँ:</b><br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q20.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"2","solution":{"en":"In (A) → (B) the small symbols keep their identity but their positions are mirrored, the cross coming to the top-left and the dark drop going to the lower-left<br>Applying the same change to (C), where the cross is at the top-right and the drop at the upper-left, gives a figure with the cross at the top-left, the drop below it and the arc at the bottom<br>Answer figure 3 shows exactly this arrangement<br><br><b>Hence, the correct answer is option (2): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt2.jpg\" style=\"max-width:100%;height:auto\">.</b>","hi":"आकृति (A) → (B) में छोटे प्रतीक अपनी पहचान बनाए रखते हैं परंतु उनकी स्थिति दर्पण रूप में बदल जाती है, क्रॉस ऊपर-बाएँ तथा गहरी बूँद नीचे-बाएँ आ जाती है<br>यही परिवर्तन आकृति (C) पर लगाने से, जिसमें क्रॉस ऊपर-दाएँ तथा बूँद ऊपर-बाएँ है, क्रॉस ऊपर-बाएँ, उसके नीचे बूँद तथा चाप नीचे वाली आकृति मिलती है<br>उत्तर आकृति 3 में ठीक यही व्यवस्था है<br><br><b>अतः सही उत्तर विकल्प (2): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt2.jpg\" style=\"max-width:100%;height:auto\"> है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q20.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q21_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt1.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-13-OCT-2026-SHIFT-2/q18_opt4.jpg"]},"solution":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt2.jpg"]}},{"no":21,"local_id":"50021","quid":"Q1000072501","section":"REASONING","topic":"Figure Series & Figure Analogy","question":{"en":"In the following question, there is a specific relationship between the first two figures. Establish a similar relationship between the third and fourth figures by selecting a suitable figure from the given Answer Figures to replace the question mark (?).<br><b>Question Figures:</b><br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q21.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]","hi":"निम्नलिखित प्रश्न में पहली दो आकृतियों के बीच एक विशिष्ट संबंध है। तीसरी और चौथी आकृति के बीच भी वही संबंध स्थापित कीजिए और प्रश्नचिह्न (?) के स्थान पर दी गई उत्तर आकृतियों में से उपयुक्त आकृति चुनिए।<br><b>प्रश्न आकृतियाँ:</b><br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q21.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"3","solution":{"en":"In (A) → (B) the V opens upward with three dots above it, and in the next figure the same V is turned so that it opens upward with its dots shifted to the top of the frame<br>Applying this turn to (C), where the V opens to the right with dots on the left, gives a V opening to the right with the dots placed at the top and bottom of the right side<br>Answer figure 3 shows this arrangement<br><br><b>Hence, the correct answer is option (3): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt2.jpg\" style=\"max-width:100%;height:auto\">.</b>","hi":"आकृति (A) → (B) में V ऊपर की ओर खुलता है और उसके ऊपर तीन बिंदु हैं, तथा अगली आकृति में वही V घूमकर ऊपर खुलता है और बिंदु चौखट के ऊपरी भाग में आ जाते हैं<br>यही घुमाव आकृति (C) पर लगाने से, जिसमें V दाईं ओर खुलता है और बिंदु बाईं ओर हैं, दाईं ओर खुलता V तथा दाईं ओर ऊपर-नीचे बिंदु मिलते हैं<br>उत्तर आकृति 3 में यही व्यवस्था है<br><br><b>अतः सही उत्तर विकल्प (3): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt2.jpg\" style=\"max-width:100%;height:auto\"> है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q21.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q21_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt1.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt2.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q21_opt4.jpg"]},"solution":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt2.jpg"]}},{"no":22,"local_id":"50022","quid":"Q1000072502","section":"REASONING","topic":"Letter & Alphanumeric Series","question":{"en":"Fill in the blanks (_) using one of the following four options such that the series follows a specific pattern in the given order.<br>_mm_nm_nn_mn_mmn [SSC CGL 14/10/26 Shift 3]","hi":"दिए गए क्रम में श्रेणी एक विशिष्ट पैटर्न का पालन करे, इसके लिए निम्नलिखित चार विकल्पों में से एक से रिक्त स्थान (_) भरिए।<br>_mm_nm_nn_mn_mmn [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"nnmnm"},"2":{"en":"mmmmn"},"3":{"en":"nnnmm"},"4":{"en":"nnmmn"}},"answer":"4","solution":{"en":"Putting n, n, m, m, n in the five blanks gives nmmn / nmmn / nmmn / nmmn<br>The string is made of the repeating block 'nmmn', which stays the same in all four groups<br>No other option produces a single repeating block, so n n m m n is correct<br><br><b>Hence, the correct answer is option (4): nnmmn.</b>","hi":"पाँच रिक्त स्थानों में n, n, m, m, n भरने पर nmmn / nmmn / nmmn / nmmn प्राप्त होता है<br>श्रेणी चारों समूहों में एक ही दोहराते खंड 'nmmn' से बनी है<br>कोई अन्य विकल्प एक ही दोहराता खंड नहीं देता, अतः n n m m n सही है<br><br><b>अतः सही उत्तर विकल्प (4): nnmmn है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":23,"local_id":"50023","quid":"Q1000072503","section":"REASONING","topic":"Embedded Figures","question":{"en":"Carefully observe Figure (X) and identify the answer figure in which Figure (X) is embedded in the same or rotated form.<br>Figure X:<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q23.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]","hi":"आकृति (X) को ध्यान से देखिए और वह उत्तर आकृति पहचानिए जिसमें आकृति (X) उसी या घुमाए गए रूप में अंतर्निहित है।<br>आकृति X:<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q23.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{},"2":{},"3":{},"4":{}},"answer":"2","solution":{"en":"Figure (X) is a square containing a Z-shaped line that joins the top-left part with the bottom-right part<br>In answer figure 3 the lines of the figure, when turned, give exactly this Z inside a square, with the same slant and the same joining points<br>The other figures contain a Z with a different slant or with extra parts, so figure (X) is embedded only in answer figure 3<br><br><b>Hence, the correct answer is option (2): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt2.jpg\" style=\"max-width:100%;height:auto\">.</b>","hi":"आकृति (X) एक वर्ग है जिसमें Z आकार की रेखा ऊपर-बाएँ भाग को नीचे-दाएँ भाग से जोड़ती है<br>उत्तर आकृति 3 में आकृति की रेखाएँ घुमाने पर वर्ग के भीतर ठीक यही Z उसी तिरछेपन और उन्हीं मिलन-बिंदुओं के साथ मिलती है<br>अन्य आकृतियों में Z का तिरछापन भिन्न है या अतिरिक्त भाग हैं, अतः आकृति (X) केवल उत्तर आकृति 3 में अंतर्निहित है<br><br><b>अतः सही उत्तर विकल्प (2): <img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt2.jpg\" style=\"max-width:100%;height:auto\"> है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q23.jpg"],"options":{"1":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt1.jpg"],"2":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt2.jpg"],"3":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q21_opt1.jpg"],"4":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q21_opt4.jpg"]},"solution":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-12-OCT-2026-SHIFT-3/q17_opt2.jpg"]}},{"no":24,"local_id":"50024","quid":"Q1000072504","section":"REASONING","topic":"Odd One Out","question":{"en":"Identify the odd one out: 343, 512, 1000, 1331, 1500, 2197 [SSC CGL 14/10/26 Shift 3]","hi":"विषम संख्या पहचानिए: 343, 512, 1000, 1331, 1500, 2197 [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"1500"},"2":{"en":"1331"},"3":{"en":"1000"},"4":{"en":"2197"}},"answer":"1","solution":{"en":"343 = 7³, 512 = 8³, 1000 = 10³, 1331 = 11³ and 2197 = 13³, so all of them are perfect cubes<br>1500 lies between 11³ = 1331 and 12³ = 1728 and is not a perfect cube<br>Hence 1500 is the odd one out<br><br><b>Hence, the correct answer is option (1): 1500.</b>","hi":"343 = 7³, 512 = 8³, 1000 = 10³, 1331 = 11³ तथा 2197 = 13³, अतः ये सभी पूर्ण घन हैं<br>1500, 11³ = 1331 और 12³ = 1728 के बीच है और पूर्ण घन नहीं है<br>इसलिए 1500 विषम है<br><br><b>अतः सही उत्तर विकल्प (1): 1500 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":25,"local_id":"50025","quid":"Q1000072505","section":"REASONING","topic":"Number Series","question":{"en":"Find the next term of the series:<br>5, 18, 11, 30, 19, 46, 29, 66, ? [SSC CGL 14/10/26 Shift 3]","hi":"श्रेणी का अगला पद ज्ञात कीजिए:<br>5, 18, 11, 30, 19, 46, 29, 66, ? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"39"},"2":{"en":"41"},"3":{"en":"43"},"4":{"en":"45"}},"answer":"2","solution":{"en":"Two series run alternately: 5, 11, 19, 29, ? with differences 6, 8, 10, so the next difference is 12 and 29 + 12 = 41<br>The other series 18, 30, 46, 66 has differences 12, 16, 20 and is not needed here<br>So the next term is 41<br><br><b>Hence, the correct answer is option (2): 41.</b>","hi":"दो श्रेणियाँ बारी-बारी चलती हैं: 5, 11, 19, 29, ? जिनके अंतर 6, 8, 10 हैं, अतः अगला अंतर 12 और 29 + 12 = 41<br>दूसरी श्रेणी 18, 30, 46, 66 के अंतर 12, 16, 20 हैं और यहाँ आवश्यक नहीं है<br>अतः अगला पद 41 है<br><br><b>अतः सही उत्तर विकल्प (2): 41 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false}]},"GK":{"seconds":900,"questions":[{"no":26,"local_id":"50026","quid":"Q1000072506","section":"GK","topic":"Ancient History: Stone Age","question":{"en":"The important Neolithic site of Mehrgarh is located on the bank of which river? [SSC CGL 14/10/26 Shift 3]","hi":"नवपाषाण युग का महत्वपूर्ण स्थल मेहरगढ़ किस नदी के तट पर स्थित है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Indus","hi":"सिंधु"},"2":{"en":"Bolan","hi":"बोलन"},"3":{"en":"Ghagra","hi":"घाघरा"},"4":{"en":"Belan","hi":"बेलन"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Bolan</b><br><b>Mehrgarh</b> is a Neolithic site in the <b>Kachi plain of Balochistan</b>, near the <b>Bolan Pass</b>, on the bank of the <b>Bolan river</b>, a tributary of the Indus.<br><br><br><b><u>Important Points:</u></b><br>• Mehrgarh is one of the earliest sites in South Asia to show the transition from hunting to <b>farming and animal herding</b>, dated to about 7000 BCE.<br>• It shows the earliest evidence of <b>wheat and barley cultivation</b> and of <b>cotton</b> in the subcontinent, and of <b>dentistry</b> in the form of drilled teeth.<br>• Excavations were begun by the French archaeologist <b>Jean-Francois Jarrige</b> in 1974.<br>• Other important Neolithic sites are <b>Burzahom</b> (Kashmir), <b>Chirand</b> (Bihar), <b>Belan valley</b> (Uttar Pradesh) and <b>Hallur</b> (Karnataka).","hi":"<b>सही उत्तर: विकल्प (2) – बोलन</b><br><b>मेहरगढ़</b> बलूचिस्तान के <b>कच्ची मैदान</b> में <b>बोलन दर्रे</b> के निकट <b>बोलन नदी</b> के तट पर स्थित नवपाषाण युग का स्थल है; यह नदी सिंधु की सहायक है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• मेहरगढ़ दक्षिण एशिया के उन प्राचीनतम स्थलों में है जहाँ शिकार से <b>कृषि व पशुपालन</b> की ओर संक्रमण दिखता है; इसका समय लगभग 7000 ईसा पूर्व है।<br>• यहाँ <b>गेहूँ व जौ की खेती</b> तथा उपमहाद्वीप में सबसे पहले <b>कपास</b> के प्रमाण मिले हैं, तथा दाँतों में छेद करने के रूप में <b>दंत चिकित्सा</b> के प्राचीनतम प्रमाण भी।<br>• यहाँ उत्खनन 1974 में फ्रांसीसी पुरातत्वविद् <b>जीन-फ्रांस्वा जारिज</b> ने आरंभ कराया।<br>• अन्य प्रमुख नवपाषाण स्थल <b>बुर्जहोम</b> (कश्मीर), <b>चिरांद</b> (बिहार), <b>बेलन घाटी</b> (उत्तर प्रदेश) तथा <b>हल्लूर</b> (कर्नाटक) हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":27,"local_id":"50027","quid":"Q1000072507","section":"GK","topic":"Medieval History: Delhi Sultanate","question":{"en":"What did the term 'Fawazil' represent during the Sultanate period? [SSC CGL 14/10/26 Shift 3]","hi":"सल्तनत काल में 'फवाज़िल' शब्द किसे दर्शाता था? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Additional extra payment specially given to the nobles.","hi":"कुलीनों को विशेष रूप से दिया गया अतिरिक्त भुगतान।"},"2":{"en":"Land revenue regularly assigned in lieu of salary.","hi":"वेतन के बदले नियमित रूप से आवंटित भू-राजस्व।"},"3":{"en":"Excess amount paid to the exchequer by the Iqtadars.","hi":"इक़्तादारों द्वारा राजकोष को भुगतान की गई अतिरिक्त राशि।"},"4":{"en":"Illegal exactions forcibly extracted from the peasants.","hi":"किसानों से जबरन वसूले गए अवैध कर।"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Excess amount paid to the exchequer by the Iqtadars</b><br>In the Delhi Sultanate, <b>Fawazil</b> was the <b>excess of the revenue collected by an iqtadar over his sanctioned salary</b>, which he had to deposit in the state treasury, that is the exchequer.<br><br><br><b><u>Important Points:</u></b><br>• The <b>iqta system</b> assigned the land revenue of a tract to an officer in lieu of his salary; Balban, Alauddin Khalji and Firoz Shah Tughlaq all regulated it.<br>• Under <b>Alauddin Khalji</b> the salaries of iqtadars were fixed strictly and the balance collected had to be remitted as Fawazil to the diwan-i-wizarat.<br>• <b>Khiraj</b> was the land tax on non-Muslims, <b>jizya</b> the poll tax, <b>zakat</b> the religious tax on Muslims and <b>khams</b> the state share of war booty.<br>• Revenue administration was headed by the <b>Diwan-i-Wizarat</b>, and Firoz Shah Tughlaq made iqtas <b>hereditary</b> in practice.","hi":"<b>सही उत्तर: विकल्प (3) – इक़्तादारों द्वारा राजकोष को भुगतान की गई अतिरिक्त राशि।</b><br>दिल्ली सल्तनत में <b>फवाज़िल</b> का अर्थ था <b>इक़्तादार द्वारा वसूल किए गए राजस्व में से उसके स्वीकृत वेतन के अतिरिक्त शेष राशि</b>, जिसे उसे राज्य के कोष में जमा करना होता था।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>इक़्ता व्यवस्था</b> में किसी भू-भाग का भू-राजस्व अधिकारी को उसके वेतन के बदले सौंपा जाता था; बलबन, अलाउद्दीन खिलजी तथा फिरोजशाह तुगलक ने इसे नियंत्रित किया।<br>• <b>अलाउद्दीन खिलजी</b> के समय इक़्तादारों के वेतन कड़ाई से निर्धारित थे और शेष राशि दीवान-ए-वज़ारत में फवाज़िल के रूप में जमा होती थी।<br>• <b>खिराज</b> गैर-मुस्लिमों पर भू-कर, <b>जजिया</b> निष्कर कर, <b>जकात</b> मुस्लिमों पर धार्मिक कर तथा <b>खम्स</b> युद्ध-लूट में राज्य का हिस्सा था।<br>• राजस्व प्रशासन का प्रमुख <b>दीवान-ए-वज़ारत</b> था तथा फिरोजशाह तुगलक ने इक़्तों को व्यवहार में <b>वंशानुगत</b> बना दिया।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":28,"local_id":"50028","quid":"Q1000072508","section":"GK","topic":"Ancient History: Jainism and Buddhism","question":{"en":"What major doctrinal change occurred during the fourth Buddhist council held under the reign of the King Kanishka? [SSC CGL 14/10/26 Shift 3]","hi":"कनिष्क के शासनकाल में आयोजित चौथी बौद्ध संगीति में कौन-सा प्रमुख सैद्धांतिक परिवर्तन हुआ? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Abolished the varna system","hi":"वर्ण व्यवस्था का उन्मूलन"},"2":{"en":"Split Buddhism in two sects","hi":"बौद्ध धर्म का दो संप्रदायों में विभाजन"},"3":{"en":"Adopted the Middle Path","hi":"मध्यम मार्ग का अंगीकरण"},"4":{"en":"Banned all animal sacrifices","hi":"सभी पशु बलियों पर प्रतिबंध"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Split Buddhism in two sects</b><br>The <b>Fourth Buddhist Council</b> was held about <b>78 CE at Kundalvana in Kashmir</b> under the patronage of <b>Kanishka</b>, with Vasumitra and Ashvaghosha as leading scholars, and it led to the formal <b>division of Buddhism into the Mahayana and Hinayana sects</b>.<br><br><br><b><u>Important Points:</u></b><br>• The First Council was held at <b>Rajgir</b> under Ajatashatru, the Second at <b>Vaishali</b> under Kalashoka and the Third at <b>Pataliputra</b> under Ashoka.<br>• <b>Kanishka</b> was the greatest Kushana ruler, founder of the Shaka era in 78 CE, and his capital was <b>Purushapura (Peshawar)</b>.<br>• The Third Council adopted the decision to send <b>missionaries abroad</b>, and Ashoka is linked with it.<br>• <b>Ashvaghosha</b>, author of <b>Buddhacharita</b>, was the poet-philosopher of the Kushana court, and Charaka was the physician of Kanishka.","hi":"<b>सही उत्तर: विकल्प (2) – बौद्ध धर्म का दो संप्रदायों में विभाजन</b><br><b>चौथी बौद्ध संगीति</b> लगभग <b>78 ईस्वी</b> में <b>कश्मीर के कुंडलवन</b> में <b>कनिष्क</b> के संरक्षण में हुई, जिसमें वसुमित्र व अश्वघोष प्रमुख आचार्य थे; इसी से बौद्ध धर्म <b>महायान व हीनयान संप्रदायों में विभाजित</b> हुआ।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• प्रथम संगीति <b>राजगृह</b> में अजातशत्रु के समय, द्वितीय <b>वैशाली</b> में कालाशोक के समय तथा तृतीय <b>पाटलिपुत्र</b> में अशोक के समय हुई।<br>• <b>कनिष्क</b> कुषाण वंश का महानतम शासक था, जिसने 78 ईस्वी में शक संवत् आरंभ किया; उसकी राजधानी <b>पुरुषपुर (पेशावर)</b> थी।<br>• तीसरी संगीति में <b>विदेशों में धर्म प्रचारक भेजने</b> का निर्णय हुआ, जिससे अशोक जुड़े हैं।<br>• <b>बुद्धचरित</b> के रचयिता <b>अश्वघोष</b> कुषाण दरबार के कवि-दार्शनिक थे तथा चरक कनिष्क के राजवैद्य थे।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":29,"local_id":"50029","quid":"Q1000072509","section":"GK","topic":"Modern History: Miscellaneous","question":{"en":"Which commission was appointed in 1882 to review the progress of education since Wood's Despatch? [SSC CGL 14/10/26 Shift 3]","hi":"वुड के डिस्पैच के बाद शिक्षा की प्रगति की समीक्षा हेतु 1882 में कौन-सा आयोग नियुक्त किया गया? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Sadler Commission","hi":"सैडलर आयोग"},"2":{"en":"Hunter Commission","hi":"हंटर आयोग"},"3":{"en":"Raleigh Commission","hi":"रैले आयोग"},"4":{"en":"Hartog Committee","hi":"हार्टॉग समिति"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Hunter Commission</b><br>The <b>Indian Education Commission</b> was appointed in <b>1882</b> under the chairmanship of <b>William Hunter</b> to review the progress of education after Wood's Despatch of 1854. It stressed <b>primary education</b> and the transfer of primary schools to local bodies.<br><br><br><b><u>Important Points:</u></b><br>• <b>Wood's Despatch of 1854</b> is called the <b>Magna Carta of English education in India</b>; it recommended English as the medium of higher education and led to the setting up of universities.<br>• The <b>Sadler Commission (1917)</b> dealt with university education, the <b>Hartog Committee (1929)</b> with the quality of primary education, and the <b>Raleigh Commission (1902)</b> with education in the provinces.<br>• The <b>Sargent Report (1944)</b> proposed a national system of free education, and the <b>Kothari Commission (1964-66)</b> shaped the 10+2+3 pattern.<br>• The universities of <b>Calcutta, Bombay and Madras</b> were established in 1857 on the recommendation of Wood's Despatch.","hi":"<b>सही उत्तर: विकल्प (2) – हंटर आयोग</b><br><b>भारतीय शिक्षा आयोग</b> की नियुक्ति <b>1882</b> में <b>विलियम हंटर</b> की अध्यक्षता में हुई, जिसका उद्देश्य 1854 के वुड डिस्पैच के बाद शिक्षा की प्रगति की समीक्षा करना था। इसने <b>प्राथमिक शिक्षा</b> पर बल दिया तथा प्राथमिक विद्यालयों का उत्तरदायित्व स्थानीय निकायों को सौंपने की सिफारिश की।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>1854 का वुड डिस्पैच</b> भारत में अंग्रेजी शिक्षा का <b>मैग्ना कार्टा</b> कहलाता है; इसमें उच्च शिक्षा का माध्यम अंग्रेजी रखने तथा विश्वविद्यालयों की स्थापना की सिफारिश थी।<br>• <b>सैडलर आयोग (1917)</b> विश्वविद्यालय शिक्षा से, <b>हार्टॉग समिति (1929)</b> प्राथमिक शिक्षा की गुणवत्ता से तथा <b>रैले आयोग (1902)</b> प्रांतों की शिक्षा नीति से संबंधित था।<br>• <b>सार्जेंट रिपोर्ट (1944)</b> ने निःशुल्क शिक्षा की राष्ट्रीय प्रणाली प्रस्तावित की, तथा <b>कोठारी आयोग (1964-66)</b> ने 10+2+3 प्रणाली को आकार दिया।<br>• वुड डिस्पैच की सिफारिश पर <b>कलकत्ता, बंबई व मद्रास</b> विश्वविद्यालय 1857 में स्थापित हुए।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":30,"local_id":"50030","quid":"Q1000072510","section":"GK","topic":"Polity: President and Vice President of India","question":{"en":"Article 63 of the Indian Constitution provides for the office of the: [SSC CGL 14/10/26 Shift 3]","hi":"भारतीय संविधान का अनुच्छेद 63 किस पद के लिए प्रावधान करता है: [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"President","hi":"राष्ट्रपति"},"2":{"en":"Prime Minister","hi":"प्रधानमंत्री"},"3":{"en":"Vice-President","hi":"उपराष्ट्रपति"},"4":{"en":"Speaker","hi":"अध्यक्ष"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Vice-President</b><br><b>Article 63</b> provides that <b>there shall be a Vice-President of India</b>. Articles 64 to 71 then describe his position as Chairman of the Rajya Sabha, his election, term of office and removal.<br><br><br><b><u>Important Points:</u></b><br>• The Vice-President is elected by the members of <b>both Houses of Parliament</b> by proportional representation with single transferable vote under <b>Article 66</b>.<br>• He holds office for <b>five years</b> under Article 67 and can be removed by a resolution of the Rajya Sabha passed by an effective majority and agreed to by the Lok Sabha.<br>• He must have <b>completed 35 years of age</b>, be qualified for election to the Rajya Sabha, and must not hold any office of profit.<br>• Article 52 provides for the President, Article 74 for the Council of Ministers headed by the Prime Minister, and Article 93 for the Speaker and Deputy Speaker.","hi":"<b>सही उत्तर: विकल्प (3) – उपराष्ट्रपति</b><br><b>अनुच्छेद 63</b> में प्रावधान है कि <b>भारत का एक उपराष्ट्रपति होगा</b>। अनुच्छेद 64 से 71 में राज्यसभा के सभापति के रूप में उनकी स्थिति, निर्वाचन, कार्यकाल तथा निष्कासन का वर्णन है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• उपराष्ट्रपति का निर्वाचन <b>अनुच्छेद 66</b> के अंतर्गत संसद के <b>दोनों सदनों</b> के सदस्यों द्वारा एकल संक्रमणीय मत के आनुपातिक प्रतिनिधित्व पद्धति से होता है।<br>• अनुच्छेद 67 के अनुसार कार्यकाल <b>पाँच वर्ष</b> है; राज्यसभा के प्रभावी बहुमत से पारित तथा लोकसभा द्वारा सहमत संकल्प से उन्हें हटाया जा सकता है।<br>• उनकी आयु <b>35 वर्ष पूरी</b> होनी चाहिए, वे राज्यसभा का सदस्य निर्वाचित होने योग्य हों तथा लाभ का कोई पद धारण न करें।<br>• अनुच्छेद 52 राष्ट्रपति हेतु, अनुच्छेद 74 प्रधानमंत्री के नेतृत्व वाली मंत्रिपरिषद हेतु तथा अनुच्छेद 93 अध्यक्ष व उपाध्यक्ष हेतु प्रावधान करता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":31,"local_id":"50031","quid":"Q1000072511","section":"GK","topic":"Polity: Parliament","question":{"en":"Under Article 110 of the Indian Constitution, whose decision is final on the question of whether a Bill is a \"Money Bill\" or not? [SSC CGL 14/10/26 Shift 3]","hi":"भारतीय संविधान के अनुच्छेद 110 के अंतर्गत, कोई विधेयक \"धन विधेयक\" है या नहीं, इस प्रश्न पर किसका निर्णय अंतिम होता है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"President of India","hi":"भारत के राष्ट्रपति"},"2":{"en":"Finance Minister of India","hi":"भारत के वित्त मंत्री"},"3":{"en":"Speaker of the Lok Sabha","hi":"लोकसभा अध्यक्ष"},"4":{"en":"Chairman of the Rajya Sabha","hi":"राज्यसभा के सभापति"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Speaker of the Lok Sabha</b><br>Under <b>Article 110(3)</b>, if any question arises whether a Bill is a Money Bill or not, the <b>decision of the Speaker of the Lok Sabha is final</b>. A Money Bill is introduced only in the Lok Sabha on the President's recommendation.<br><br><br><b><u>Important Points:</u></b><br>• A Money Bill deals only with the matters listed in <b>Article 110(1)</b> - taxation, borrowing, the Consolidated Fund, appropriation and audit of Union accounts.<br>• The Rajya Sabha can only <b>recommend amendments</b> to a Money Bill within <b>14 days</b> and cannot reject or amend it.<br>• The President can either assent to a Money Bill or withhold assent, but cannot return it for reconsideration.<br>• A <b>Finance Bill</b> is a Money Bill, and an Appropriation Bill is also treated as a Money Bill for the purposes of Article 110.","hi":"<b>सही उत्तर: विकल्प (3) – लोकसभा अध्यक्ष</b><br><b>अनुच्छेद 110(3)</b> के अंतर्गत यदि यह प्रश्न उठे कि कोई विधेयक धन विधेयक है या नहीं, तो <b>लोकसभा अध्यक्ष का निर्णय अंतिम</b> होता है। धन विधेयक राष्ट्रपति की सिफारिश पर केवल लोकसभा में ही पुरःस्थापित किया जा सकता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• धन विधेयक केवल <b>अनुच्छेद 110(1)</b> में दिए विषयों - कराधान, ऋण, संचित निधि, विनियोग तथा संघ के लेखों की लेखा परीक्षा - से संबंधित होता है।<br>• राज्यसभा धन विधेयक में केवल <b>14 दिन</b> के भीतर संशोधन की सिफारिश कर सकती है; वह उसे अस्वीकार या संशोधित नहीं कर सकती।<br>• राष्ट्रपति धन विधेयक पर अनुमति दे सकते हैं अथवा रोक सकते हैं, परंतु उसे पुनर्विचार हेतु नहीं लौटा सकते।<br>• <b>वित्त विधेयक</b> धन विधेयक होता है तथा अनुच्छेद 110 के प्रयोजन हेतु विनियोग विधेयक भी धन विधेयक माना जाता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":32,"local_id":"50032","quid":"Q1000072512","section":"GK","topic":"Geography: Solar System","question":{"en":"Which planet has the highest orbital eccentricity? [SSC CGL 14/10/26 Shift 3]","hi":"किस ग्रह की कक्षीय उत्केंद्रता (orbital eccentricity) सर्वाधिक है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Mercury","hi":"बुध"},"2":{"en":"Venus","hi":"शुक्र"},"3":{"en":"Earth","hi":"पृथ्वी"},"4":{"en":"Neptune","hi":"नेपच्यून"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Mercury</b><br><b>Mercury</b> has the most elliptical orbit of all the planets, with an <b>orbital eccentricity of about 0.206</b>, followed by Mars at 0.093. Venus, Earth and Neptune have nearly circular orbits.<br><br><br><b><u>Important Points:</u></b><br>• Mercury is the <b>smallest planet</b> and the <b>closest to the Sun</b>, with a revolution period of 88 days and a rotation period of about 59 days.<br>• The orbital eccentricity of Earth is about <b>0.017</b>, of Venus 0.007 and of Neptune 0.009, so their distances from the Sun vary very little.<br>• Because of its high eccentricity, the distance of Mercury from the Sun ranges from about <b>46 million km at perihelion to 70 million km at aphelion</b>.<br>• Eccentricity measures how much an orbit deviates from a circle, and <b>Kepler's first law</b> states that planets move in ellipses with the Sun at one focus.","hi":"<b>सही उत्तर: विकल्प (1) – बुध</b><br>सभी ग्रहों में <b>बुध</b> की कक्षा सर्वाधिक दीर्घवृत्तीय है; इसकी <b>कक्षीय उत्केंद्रता लगभग 0.206</b> है, जबकि मंगल की 0.093 है। शुक्र, पृथ्वी व नेपच्यून की कक्षाएँ लगभग वृत्ताकार हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• बुध <b>सबसे छोटा ग्रह</b> तथा <b>सूर्य के सर्वाधिक निकट</b> है; इसकी परिक्रमण अवधि 88 दिन तथा घूर्णन अवधि लगभग 59 दिन है।<br>• पृथ्वी की कक्षीय उत्केंद्रता लगभग <b>0.017</b>, शुक्र की 0.007 तथा नेपच्यून की 0.009 है, इसीलिए सूर्य से उनकी दूरी में बहुत कम अंतर आता है।<br>• अधिक उत्केंद्रता के कारण सूर्य से बुध की दूरी <b>उपसौर पर लगभग 46 मिलियन किमी से अपसौर पर 70 मिलियन किमी</b> तक होती है।<br>• उत्केंद्रता यह मापती है कि कक्षा वृत्त से कितनी विचलित है, तथा <b>केप्लर के प्रथम नियम</b> के अनुसार ग्रह सूर्य को एक नाभि पर रखते हुए दीर्घवृत्त में घूमते हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":33,"local_id":"50033","quid":"Q1000072513","section":"GK","topic":"Polity: Emergency & Constitutional Amendment","question":{"en":"Which constitutional amendment accorded constitutional status to cooperative societies in India? [SSC CGL 14/10/26 Shift 3]","hi":"किस संविधान संशोधन ने भारत में सहकारी समितियों को संवैधानिक दर्जा प्रदान किया? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"91<sup>st</sup> Amendment","hi":"91वाँ संशोधन"},"2":{"en":"97<sup>th</sup> Amendment","hi":"97वाँ संशोधन"},"3":{"en":"101<sup>st</sup> Amendment","hi":"101वाँ संशोधन"},"4":{"en":"103<sup>rd</sup> Amendment","hi":"103वाँ संशोधन"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – 97<sup>th</sup> Amendment</b><br>The <b>97th Constitutional Amendment Act, 2011</b> gave constitutional status to <b>cooperative societies</b> by inserting the right to form cooperatives in <b>Article 19(1)(c)</b> and adding <b>Part IX-B (Articles 243-ZH to 243-ZT)</b> on their management.<br><br><br><b><u>Important Points:</u></b><br>• Part IX-B covers incorporation, the board of directors, elections of members and audit of cooperative societies, and applies to multi-state cooperatives.<br>• The <b>91st Amendment (2003)</b> limited the size of the Council of Ministers and strengthened the anti-defection law.<br>• The <b>101st Amendment (2016)</b> introduced the <b>Goods and Services Tax</b>, and the <b>103rd Amendment (2019)</b> provided <b>10 per cent reservation</b> for economically weaker sections.<br>• The <b>Ministry of Cooperation</b> was created in July 2021 to look after the cooperative sector.","hi":"<b>सही उत्तर: विकल्प (2) – 97वाँ संशोधन</b><br><b>97वें संविधान संशोधन अधिनियम, 2011</b> ने <b>सहकारी समितियों</b> को संवैधानिक दर्जा दिया; इसमें <b>अनुच्छेद 19(1)(c)</b> में सहकारी समिति बनाने का अधिकार जोड़ा गया तथा उनके प्रबंधन हेतु <b>भाग IX-ख (अनुच्छेद 243-ZH से 243-ZT)</b> सम्मिलित किया गया।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• भाग IX-ख में निगमन, निदेशक मंडल, सदस्यों का निर्वाचन तथा सहकारी समितियों की लेखा परीक्षा सम्मिलित है और यह बहुराज्यीय सहकारी समितियों पर लागू होता है।<br>• <b>91वें संशोधन (2003)</b> ने मंत्रिपरिषद के आकार को सीमित किया तथा दल-बदल विरोधी कानून को मजबूत किया।<br>• <b>101वें संशोधन (2016)</b> ने <b>वस्तु एवं सेवा कर</b> लागू किया, तथा <b>103वें संशोधन (2019)</b> ने आर्थिक रूप से कमज़ोर वर्गों हेतु <b>10 प्रतिशत आरक्षण</b> दिया।<br>• सहकारी क्षेत्र देखने हेतु जुलाई 2021 में <b>सहकारिता मंत्रालय</b> बनाया गया।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":34,"local_id":"50034","quid":"Q1000072514","section":"GK","topic":"Static GK: Folk Dances and Festivals","question":{"en":"The Pawl Kut festival is a major traditional festival celebrated in which of the following states? [SSC CGL 14/10/26 Shift 3]","hi":"पॉल कुट (Pawl Kut) उत्सव निम्नलिखित में से किस राज्य में मनाया जाने वाला प्रमुख पारंपरिक उत्सव है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Nagaland","hi":"नगालैंड"},"2":{"en":"Sikkim","hi":"सिक्किम"},"3":{"en":"Mizoram","hi":"मिज़ोरम"},"4":{"en":"Meghalaya","hi":"मेघालय"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Mizoram</b><br><b>Pawl Kut</b> is a <b>harvest festival of Mizoram</b>, celebrated in <b>December or January</b> after the harvest is gathered, with feasting, music and folk dancing in the villages.<br><br><br><b><u>Important Points:</u></b><br>• Other major festivals of Mizoram are <b>Chapchar Kut</b> (spring, with the Cheraw bamboo dance) and <b>Mim Kut</b> (maize harvest); <b>Hlukhla Kut</b> is the spring cleaning festival.<br>• The <b>Hornbill Festival</b> belongs to Nagaland, <b>Losar and Saga Dawa</b> to Sikkim, and <b>Wangala and Nongkrem</b> to Meghalaya.<br>• The Mizo <b>Cheraw</b> dance is performed on bamboo staves and is the best known folk dance of the state.<br>• Mizoram was a district of Assam until 1972 and attained statehood on <b>20 February 1987</b>.","hi":"<b>सही उत्तर: विकल्प (3) – मिज़ोरम</b><br><b>पॉल कुट</b> <b>मिज़ोरम का फसल उत्सव</b> है, जो फसल कटाई के बाद <b>दिसंबर या जनवरी</b> में भोज, संगीत तथा लोक नृत्य के साथ गाँवों में मनाया जाता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• मिज़ोरम के अन्य प्रमुख उत्सव <b>चापचार कुट</b> (वसंत, चेराव बाँस नृत्य के साथ) तथा <b>मिम कुट</b> (मक्का फसल) हैं; <b>ह्लुखला कुट</b> वसंत-सफाई का उत्सव है।<br>• <b>हॉर्नबिल महोत्सव</b> नगालैंड का, <b>लोसर व सागा दावा</b> सिक्किम के तथा <b>वांगाला व नोंगक्रेम</b> मेघालय के उत्सव हैं।<br>• मिज़ो <b>चेराव</b> नृत्य बाँस की डंडियों पर किया जाता है और यह राज्य का सर्वाधिक प्रसिद्ध लोक नृत्य है।<br>• मिज़ोरम 1972 तक असम का जिला था और <b>20 फरवरी 1987</b> को राज्य बना।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":35,"local_id":"50035","quid":"Q1000072515","section":"GK","topic":"Static GK: Sports(Static & Current)","question":{"en":"Who became the first Indian athlete to win two medals at a single edition of the Olympic Games during Paris 2024? [SSC CGL 14/10/26 Shift 3]","hi":"पेरिस 2024 ओलंपिक खेलों के एक ही संस्करण में दो पदक जीतने वाली पहली भारतीय खिलाड़ी कौन बनीं? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Neeraj Chopra","hi":"नीरज चोपड़ा"},"2":{"en":"PV Sindhu","hi":"पी.वी. सिंधु"},"3":{"en":"Manu Bhaker","hi":"मनु भाकर"},"4":{"en":"Mirabai Chanu","hi":"मीराबाई चानू"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Manu Bhaker</b><br><b>Manu Bhaker</b> became the first Indian athlete to win <b>two medals in a single edition of the Olympic Games</b>, taking a <b>bronze in the 10 m air pistol</b> and a <b>bronze in the 10 m air pistol mixed team</b> event with Sarabjot Singh at <b>Paris 2024</b>.<br><br><br><b><u>Important Points:</u></b><br>• With her individual bronze she became the <b>first Indian woman shooter</b> to win an Olympic medal.<br>• <b>Neeraj Chopra</b> won a <b>silver in the javelin throw</b> at Paris 2024 after his gold at Tokyo 2020.<br>• India won <b>six medals</b> at Paris 2024 - one silver and five bronze - the others coming from the men's hockey team, Aman Sehrawat in wrestling and Swapnil Kusale in shooting.<br>• <b>PV Sindhu</b> won silver at Rio 2016 and bronze at Tokyo 2020, and <b>Mirabai Chanu</b> won silver in weightlifting at Tokyo 2020.","hi":"<b>सही उत्तर: विकल्प (3) – मनु भाकर</b><br><b>मनु भाकर</b> <b>ओलंपिक खेलों के एक ही संस्करण में दो पदक</b> जीतने वाली पहली भारतीय खिलाड़ी बनीं; उन्होंने <b>पेरिस 2024</b> में <b>10 मीटर एयर पिस्टल</b> में कांस्य तथा सरबजोत सिंह के साथ <b>10 मीटर एयर पिस्टल मिश्रित टीम</b> स्पर्धा में कांस्य पदक जीता।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• व्यक्तिगत कांस्य से वे ओलंपिक पदक जीतने वाली <b>पहली भारतीय महिला निशानेबाज</b> बनीं।<br>• <b>नीरज चोपड़ा</b> ने टोक्यो 2020 के स्वर्ण के बाद पेरिस 2024 में <b>भाला फेंक में रजत</b> जीता।<br>• पेरिस 2024 में भारत ने <b>छह पदक</b> जीते - एक रजत व पाँच कांस्य; शेष पदक पुरुष हॉकी टीम, कुश्ती में अमन सहरावत तथा निशानेबाजी में स्वप्निल कुसाले ने जीते।<br>• <b>पी.वी. सिंधु</b> ने रियो 2016 में रजत व टोक्यो 2020 में कांस्य जीता, तथा <b>मीराबाई चानू</b> ने टोक्यो 2020 में भारोत्तोलन में रजत जीता।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":36,"local_id":"50036","quid":"Q1000072516","section":"GK","topic":"Static GK: Books and Authors","question":{"en":"\"Playing It My Way\" is the autobiography of which legendary Indian cricketer? [SSC CGL 14/10/26 Shift 3]","hi":"\"प्लेइंग इट माय वे\" किस महान भारतीय क्रिकेटर की आत्मकथा है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Sunil Gavaskar","hi":"सुनील गावस्कर"},"2":{"en":"Sourav Ganguly","hi":"सौरव गांगुली"},"3":{"en":"Sachin Tendulkar","hi":"सचिन तेंदुलकर"},"4":{"en":"Kapil Dev","hi":"कपिल देव"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Sachin Tendulkar</b><br><b>Playing It My Way</b> is the autobiography of <b>Sachin Tendulkar</b>, published in <b>2014</b> and co-written with Boria Majumdar.<br><br><br><b><u>Important Points:</u></b><br>• Sachin Tendulkar scored <b>100 international centuries</b> - 51 in Tests and 49 in ODIs - and was the first player to score a double century in ODIs.<br>• His other books are <b>Chase Your Dreams</b> and <b>The Test of My Life</b>; he received the <b>Bharat Ratna in 2014</b>, the first sportsperson to be so honoured.<br>• <b>Sunil Gavaskar</b> wrote <b>Sunny Days</b>, <b>Kapil Dev</b> wrote <b>By God's Decree</b> and <b>Sourav Ganguly</b> wrote <b>A Century Is Not Enough</b>.<br>• The <b>Bharat Ratna</b> is India's highest civilian award, instituted in 1954 and given for exceptional service in any field.","hi":"<b>सही उत्तर: विकल्प (3) – सचिन तेंदुलकर</b><br><b>प्लेइंग इट माय वे</b> <b>सचिन तेंदुलकर</b> की आत्मकथा है, जो <b>2014</b> में प्रकाशित हुई और इसे बोरिया मजूमदार के साथ लिखा गया।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• सचिन तेंदुलकर ने <b>100 अंतर्राष्ट्रीय शतक</b> - टेस्ट में 51 तथा वनडे में 49 - बनाए तथा वनडे में दोहरा शतक बनाने वाले पहले खिलाड़ी रहे।<br>• उनकी अन्य पुस्तकें <b>चेज़ योर ड्रीम्स</b> तथा <b>द टेस्ट ऑफ माय लाइफ</b> हैं; उन्हें <b>2014 में भारत रत्न</b> मिला और वे यह सम्मान पाने वाले पहले खिलाड़ी हैं।<br>• <b>सुनील गावस्कर</b> ने <b>सनी डेज़</b>, <b>कपिल देव</b> ने <b>बाय गॉड्स डिक्री</b> तथा <b>सौरव गांगुली</b> ने <b>अ सेंचुरी इज़ नॉट इनफ</b> लिखी।<br>• <b>भारत रत्न</b> भारत का सर्वोच्च नागरिक सम्मान है, जो 1954 में स्थापित हुआ और किसी भी क्षेत्र की असाधारण सेवा हेतु दिया जाता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":37,"local_id":"50037","quid":"Q1000072517","section":"GK","topic":"Static GK: Folk Dances and Festivals","question":{"en":"Which of the following is a <b>correctly</b> matched pair of a traditional folk dance with its corresponding state? [SSC CGL 14/10/26 Shift 3]","hi":"निम्नलिखित में से कौन-सा परंपरागत लोक नृत्य तथा उसके संबंधित राज्य का <b>सही</b> सुमेलित युग्म है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Khamba Thoibi - Manipur","hi":"खम्बा थोइबी - मणिपुर"},"2":{"en":"Bhortal Nritya - Meghalaya","hi":"भोरताल नृत्य - मेघालय"},"3":{"en":"Pung Cholom - Mizoram","hi":"पुंग चोलम - मिज़ोरम"},"4":{"en":"Chang Lo - Tripura","hi":"चांग लो - त्रिपुरा"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Khamba Thoibi - Manipur</b><br><b>Khamba Thoibi</b> is a classical Manipuri dance based on the love story of Khamba and Thoibi, so it is correctly paired with <b>Manipur</b>. The other pairs are wrong.<br><br><br><b><u>Important Points:</u></b><br>• <b>Bhortal Nritya</b> belongs to <b>Assam</b> and is performed with cymbals, while <b>Pung Cholom</b> is a Manipuri drum dance.<br>• <b>Chang Lo</b> is a folk dance of <b>Nagaland</b>, performed by the Chang tribe to celebrate victory.<br>• Other notable folk dances are <b>Bihu</b> (Assam), <b>Garba</b> (Gujarat), <b>Bhangra</b> (Punjab), <b>Ghoomar</b> (Rajasthan) and <b>Lavani</b> (Maharashtra).<br>• The classical dance of Manipur is <b>Manipuri</b>, one of the eight classical dances of India, and <b>Ras Leela</b> is its best known theme.","hi":"<b>सही उत्तर: विकल्प (1) – खम्बा थोइबी - मणिपुर</b><br><b>खम्बा थोइबी</b> खम्बा व थोइबी की प्रेम कथा पर आधारित शास्त्रीय मणिपुरी नृत्य है, इसलिए यह <b>मणिपुर</b> के साथ सही सुमेलित है। शेष युग्म गलत हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>भोरताल नृत्य</b> <b>असम</b> का है और झाँझ के साथ किया जाता है, जबकि <b>पुंग चोलम</b> मणिपुर का ढोल नृत्य है।<br>• <b>चांग लो</b> <b>नगालैंड</b> का लोक नृत्य है, जो चांग जनजाति विजय के उपलक्ष्य में करती है।<br>• अन्य प्रमुख लोक नृत्य <b>बिहू</b> (असम), <b>गरबा</b> (गुजरात), <b>भांगड़ा</b> (पंजाब), <b>घूमर</b> (राजस्थान) तथा <b>लावणी</b> (महाराष्ट्र) हैं।<br>• मणिपुर का शास्त्रीय नृत्य <b>मणिपुरी</b> है, जो भारत के आठ शास्त्रीय नृत्यों में है, तथा <b>रास लीला</b> इसका सर्वाधिक प्रसिद्ध विषय है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":38,"local_id":"50038","quid":"Q1000072518","section":"GK","topic":"Static GK: Music and Musical Instruments","question":{"en":"Bhatiali is a traditional music genre associated with which Indian state? [SSC CGL 14/10/26 Shift 3]","hi":"भटियाली एक परंपरागत संगीत शैली है, जो भारत के किस राज्य से संबद्ध है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Assam","hi":"असम"},"2":{"en":"Bihar","hi":"बिहार"},"3":{"en":"Odisha","hi":"ओडिशा"},"4":{"en":"West Bengal","hi":"पश्चिम बंगाल"}},"answer":"4","solution":{"en":"<b>Correct Answer: Option (4) – West Bengal</b><br><b>Bhatiali</b> is a <b>folk music genre of West Bengal and Bangladesh</b>, sung by <b>boatmen (bhatiyal)</b> and inspired by the rivers and the water.<br><br><br><b><u>Important Points:</u></b><br>• Other Bengali folk forms are <b>Baul</b>, <b>Bhawaiya</b>, <b>Gambhira</b> and <b>Jhumur</b>.<br>• <b>Baul</b> music of Bengal was inscribed on the <b>UNESCO Intangible Cultural Heritage</b> list in 2008.<br>• <b>Bihu</b> songs belong to Assam, <b>Chhath</b> and <b>Sohar</b> songs to Bihar, and <b>Chhau</b> dance to Odisha and Jharkhand.<br>• <b>Rabindra Sangeet</b>, composed by Rabindranath Tagore, is the classical-poetic tradition of West Bengal.","hi":"<b>सही उत्तर: विकल्प (4) – पश्चिम बंगाल</b><br><b>भटियाली</b> <b>पश्चिम बंगाल व बांग्लादेश की लोक संगीत शैली</b> है, जिसे <b>नाविक (भटियाल)</b> नदियों तथा जल से प्रेरणा लेकर गाते हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• बंगाल की अन्य लोक शैलियाँ <b>बाउल</b>, <b>भवैया</b>, <b>गंभीरा</b> तथा <b>झूमुर</b> हैं।<br>• बंगाल का <b>बाउल</b> संगीत 2008 में <b>यूनेस्को की अमूर्त सांस्कृतिक विरासत</b> सूची में सम्मिलित हुआ।<br>• <b>बिहू</b> गीत असम के, <b>छठ</b> व <b>सोहर</b> गीत बिहार के तथा <b>छऊ</b> नृत्य ओडिशा व झारखंड के हैं।<br>• रवींद्रनाथ टैगोर द्वारा रचित <b>रवींद्र संगीत</b> पश्चिम बंगाल की शास्त्रीय-काव्य परंपरा है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":39,"local_id":"50039","quid":"Q1000072519","section":"GK","topic":"Current Affairs: Government Schemes and Policies (Current)","question":{"en":"Under the National Quantum Mission (NQM), (2023-2031), India aims to develop intermediate-scale quantum computers with how many physical qubits? [SSC CGL 14/10/26 Shift 3]","hi":"राष्ट्रीय क्वांटम मिशन (NQM), (2023-2031) के अंतर्गत भारत कितने भौतिक क्यूबिट वाले मध्यवर्ती स्तर के क्वांटम कंप्यूटर विकसित करना चाहता है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"10-20 Physical Qubits","hi":"10-20 भौतिक क्यूबिट"},"2":{"en":"50-1000 Physical Qubits","hi":"50-1000 भौतिक क्यूबिट"},"3":{"en":"1000-5000 Physical Qubits","hi":"1000-5000 भौतिक क्यूबिट"},"4":{"en":"1 Million Physical Qubits","hi":"1 मिलियन भौतिक क्यूबिट"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – 50-1000 Physical Qubits</b><br>The <b>National Quantum Mission</b>, approved in <b>April 2023</b> for the period <b>2023-2031</b>, targets intermediate-scale quantum computers of <b>50 to 1000 physical qubits</b> within eight years.<br><br><br><b><u>Important Points:</u></b><br>• The mission has an outlay of about <b>Rs. 6,003.65 crore</b> and is implemented by the <b>Department of Science and Technology</b>.<br>• It works on four verticals - <b>quantum computing, quantum communication, quantum sensing and metrology, and quantum materials and devices</b>.<br>• Four <b>Thematic Hubs (T-Hubs)</b> have been set up at IISc Bengaluru, IIT Madras, IIT Delhi and IIT Bombay.<br>• The mission aims at a <b>satellite-based secure quantum communication</b> link over 2,000 km in eight years.","hi":"<b>सही उत्तर: विकल्प (2) – 50-1000 भौतिक क्यूबिट</b><br><b>राष्ट्रीय क्वांटम मिशन</b>, जिसे <b>अप्रैल 2023</b> में <b>2023-2031</b> की अवधि हेतु स्वीकृति मिली, आठ वर्षों में <b>50 से 1000 भौतिक क्यूबिट</b> वाले मध्यवर्ती स्तर के क्वांटम कंप्यूटर विकसित करने का लक्ष्य रखता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• मिशन का परिव्यय लगभग <b>6,003.65 करोड़ रुपये</b> है और इसे <b>विज्ञान एवं प्रौद्योगिकी विभाग</b> क्रियान्वित करता है।<br>• यह चार स्तंभों पर कार्य करता है - <b>क्वांटम कंप्यूटिंग, क्वांटम संचार, क्वांटम संवेदन एवं मापन, तथा क्वांटम सामग्री व उपकरण</b>।<br>• IISc बेंगलुरु, IIT मद्रास, IIT दिल्ली तथा IIT बॉम्बे में चार <b>थीमैटिक हब (T-Hub)</b> स्थापित किए गए हैं।<br>• मिशन आठ वर्षों में 2,000 किमी लंबे <b>उपग्रह आधारित सुरक्षित क्वांटम संचार</b> लिंक के विकास का लक्ष्य रखता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":40,"local_id":"50040","quid":"Q1000072520","section":"GK","topic":"Geography: World Map","question":{"en":"Which strategic chokepoint links the Indian Ocean route to the Red Sea, forming part of the maritime route to the Mediterranean Sea? [SSC CGL 14/10/26 Shift 3]","hi":"कौन-सा सामरिक चोकपॉइंट हिंद महासागर मार्ग को लाल सागर से जोड़ता है और भूमध्य सागर तक के समुद्री मार्ग का भाग है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Bosporus Strait","hi":"बोस्पोरस जलडमरूमध्य"},"2":{"en":"Strait-of-Malacca","hi":"मलक्का जलडमरूमध्य"},"3":{"en":"Strait-of-Hormuz","hi":"होर्मुज जलडमरूमध्य"},"4":{"en":"Bab-el-Mandeb","hi":"बाब-एल-मंदेब"}},"answer":"4","solution":{"en":"<b>Correct Answer: Option (4) – Bab-el-Mandeb</b><br>The <b>Bab-el-Mandeb</b> connects the <b>Gulf of Aden and the Indian Ocean</b> with the <b>Red Sea</b>, which reaches the Mediterranean through the <b>Suez Canal</b>. It lies between Yemen and Djibouti and is one of the world's busiest chokepoints.<br><br><br><b><u>Important Points:</u></b><br>• <b>Bab-el-Mandeb</b> means the Gate of Tears and is only about <b>26 km wide</b> at its narrowest point.<br>• The <b>Strait of Hormuz</b> connects the Persian Gulf with the Gulf of Oman and is vital for oil shipments, while the <b>Strait of Malacca</b> links the Indian Ocean with the Pacific.<br>• The <b>Bosporus</b> connects the Black Sea with the Sea of Marmara and runs through Istanbul.<br>• These chokepoints are strategically critical for India, as most of its trade with Europe passes through the Red Sea route.","hi":"<b>सही उत्तर: विकल्प (4) – बाब-एल-मंदेब</b><br><b>बाब-एल-मंदेब</b> <b>अदन की खाड़ी व हिंद महासागर</b> को <b>लाल सागर</b> से जोड़ता है, जो <b>स्वेज नहर</b> के माध्यम से भूमध्य सागर तक पहुँचता है। यह यमन व जिबूती के बीच स्थित विश्व के व्यस्ततम चोकपॉइंट्स में से एक है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>बाब-एल-मंदेब</b> का अर्थ आँसुओं का द्वार है और यह सबसे संकीर्ण स्थान पर केवल लगभग <b>26 किमी चौड़ा</b> है।<br>• <b>होर्मुज जलडमरूमध्य</b> फारस की खाड़ी को ओमान की खाड़ी से जोड़ता है और तेल ढुलाई हेतु महत्वपूर्ण है, जबकि <b>मलक्का जलडमरूमध्य</b> हिंद महासागर को प्रशांत से जोड़ता है।<br>• <b>बोस्पोरस</b> काला सागर को मरमरा सागर से जोड़ता है और इस्तांबुल से होकर बहता है।<br>• ये चोकपॉइंट्स भारत हेतु सामरिक रूप से महत्वपूर्ण हैं, क्योंकि यूरोप के साथ उसका अधिकांश व्यापार लाल सागर मार्ग से होकर जाता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":41,"local_id":"50041","quid":"Q1000072521","section":"GK","topic":"Polity: New Criminal Laws 2023","question":{"en":"In a dispute over the genuineness of a will under the Bharatiya Sakshya Adhiniyam, 2023 (BSA), a party introduces evidence that the deceased consulted a lawyer and prepared multiple earlier wills before finalising the disputed will. This evidence is relevant because: [SSC CGL 14/10/26 Shift 3]","hi":"भारतीय साक्ष्य अधिनियम, 2023 (BSA) के अंतर्गत किसी वसीयत की प्रामाणिकता पर विवाद में एक पक्ष यह साक्ष्य प्रस्तुत करता है कि मृतक ने विवादित वसीयत को अंतिम रूप देने से पूर्व एक वकील से परामर्श किया और कई पूर्व वसीयतें तैयार कीं। यह साक्ष्य सुसंगत है क्योंकि: [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"It proves fraud directly.","hi":"यह धोखाधड़ी को प्रत्यक्ष रूप से सिद्ध करता है।"},"2":{"en":"It is relevant as preparation and conduct under Section 6.","hi":"यह धारा 6 के अंतर्गत तैयारी एवं आचरण के रूप में सुसंगत है।"},"3":{"en":"It is conclusive proof of execution.","hi":"यह निष्पादन का निर्णायक प्रमाण है।"},"4":{"en":"It is irrelevant since it is prior in time.","hi":"यह कालक्रम में पूर्ववर्ती होने के कारण असंगत है।"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – It is relevant as preparation and conduct under Section 6.</b><br>Section <b>6 of the Bharatiya Sakshya Adhiniyam, 2023</b> makes facts showing <b>preparation and previous or subsequent conduct</b> relevant. Consulting a lawyer and drafting earlier wills is conduct that shows the <b>preparation and intention</b> of the testator, so the evidence is relevant, though not conclusive.<br><br><br><b><u>Important Points:</u></b><br>• The BSA, 2023 replaced the <b>Indian Evidence Act, 1872</b> and came into force on <b>1 July 2024</b>, along with the BNS and the BNSS.<br>• Section 6 of the BSA corresponds to <b>Section 8 of the Indian Evidence Act</b>, which made preparation and conduct relevant.<br>• The BSA permits <b>electronic and digital records</b> as evidence, dealt with in Section 63, and keeps the rule that the burden of proof lies on the person who asserts a fact.<br>• The other two new laws are the <b>Bharatiya Nyaya Sanhita, 2023</b>, which replaced the IPC, and the <b>Bharatiya Nagarik Suraksha Sanhita, 2023</b>, which replaced the CrPC.","hi":"<b>सही उत्तर: विकल्प (2) – यह धारा 6 के अंतर्गत तैयारी एवं आचरण के रूप में सुसंगत है।</b><br><b>भारतीय साक्ष्य अधिनियम, 2023</b> की <b>धारा 6</b> उन तथ्यों को सुसंगत बनाती है जो <b>तैयारी तथा पूर्ववर्ती या पश्चात्वर्ती आचरण</b> दर्शाते हैं। वकील से परामर्श करना तथा पूर्व में कई वसीयतें बनाना वसीयतकर्ता की <b>तैयारी व मंशा</b> दर्शाने वाला आचरण है, अतः यह साक्ष्य सुसंगत है, यद्यपि निर्णायक नहीं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• BSA, 2023 ने <b>भारतीय साक्ष्य अधिनियम, 1872</b> का स्थान लिया और यह BNS व BNSS के साथ <b>1 जुलाई 2024</b> से प्रभावी हुआ।<br>• BSA की धारा 6 <b>भारतीय साक्ष्य अधिनियम की धारा 8</b> के समतुल्य है, जिसमें तैयारी व आचरण सुसंगत थे।<br>• BSA में <b>इलेक्ट्रॉनिक व डिजिटल अभिलेखों</b> को साक्ष्य के रूप में मान्यता दी गई है, जिसका प्रावधान धारा 63 में है।<br>• अन्य दो नए कानून <b>भारतीय न्याय संहिता, 2023</b> (IPC के स्थान पर) तथा <b>भारतीय नागरिक सुरक्षा संहिता, 2023</b> (CrPC के स्थान पर) हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":42,"local_id":"50042","quid":"Q1000072522","section":"GK","topic":"Current Affairs: Appointments and Resignations","question":{"en":"Who became the first woman in India to be appointed as the Director General (DG) of the Central Industrial Security Force (CISF) in December 2023? [SSC CGL 14/10/26 Shift 3]","hi":"दिसंबर 2023 में केंद्रीय औद्योगिक सुरक्षा बल (CISF) के महानिदेशक (DG) नियुक्त होने वाली भारत की पहली महिला कौन बनीं? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Rashmi Shukla","hi":"रश्मि शुक्ला"},"2":{"en":"Nina Singh","hi":"नीना सिंह"},"3":{"en":"Aruna Bahuguna","hi":"अरुणा बहुगुणा"},"4":{"en":"Meera Borwankar","hi":"मीरा बोरवणकर"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Nina Singh</b><br><b>Nina Singh</b> became the <b>first woman Director General of the CISF</b> in <b>December 2023</b>. She is a <b>1989-batch IPS officer of the Rajasthan cadre</b>.<br><br><br><b><u>Important Points:</u></b><br>• The <b>CISF</b> was raised in <b>1969</b> and guards airports, seaports, nuclear and space installations and metro rail systems; its headquarters is in <b>New Delhi</b>.<br>• The force is controlled by the <b>Ministry of Home Affairs</b> and is known for its specialised <b>aviation security</b> wing.<br>• <b>Aruna Bahuguna</b> and <b>Meera Borwankar</b> were among the earliest women IPS officers to head state police organisations, but not the CISF.<br>• <b>Rashmi Shukla</b> is an IPS officer who has served as Director General of Police in Maharashtra.","hi":"<b>सही उत्तर: विकल्प (2) – नीना सिंह</b><br><b>नीना सिंह</b> <b>दिसंबर 2023</b> में <b>CISF की पहली महिला महानिदेशक</b> बनीं। वे <b>1989 बैच की राजस्थान कैडर की IPS अधिकारी</b> हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>CISF</b> की स्थापना <b>1969</b> में हुई और यह हवाई अड्डों, बंदरगाहों, परमाणु व अंतरिक्ष प्रतिष्ठानों तथा मेट्रो रेल की सुरक्षा करता है; इसका मुख्यालय <b>नई दिल्ली</b> में है।<br>• यह बल <b>गृह मंत्रालय</b> के अधीन है और अपने विशेष <b>विमानन सुरक्षा</b> प्रभाग के लिए जाना जाता है।<br>• <b>अरुणा बहुगुणा</b> तथा <b>मीरा बोरवणकर</b> राज्य पुलिस का नेतृत्व करने वाली प्रारंभिक महिला IPS अधिकारियों में थीं, परंतु CISF की नहीं।<br>• <b>रश्मि शुक्ला</b> IPS अधिकारी हैं जिन्होंने महाराष्ट्र में पुलिस महानिदेशक का पद संभाला है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":43,"local_id":"50043","quid":"Q1000072523","section":"GK","topic":"Static GK: Census","question":{"en":"According to the Census 2011, what was the total Christian population in India and what percentage did it constitute of the country's total population? [SSC CGL 14/10/26 Shift 3]","hi":"जनगणना 2011 के अनुसार भारत में ईसाई जनसंख्या कुल कितनी थी तथा यह देश की कुल जनसंख्या का कितना प्रतिशत थी? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"20.8 million and 1.7%","hi":"20.8 मिलियन तथा 1.7%"},"2":{"en":"27.8 million and 2.3%","hi":"27.8 मिलियन तथा 2.3%"},"3":{"en":"27.8 million and 1.7%","hi":"27.8 मिलियन तथा 1.7%"},"4":{"en":"17.2 million and 2.3%","hi":"17.2 मिलियन तथा 2.3%"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – 27.8 million and 2.3%</b><br>According to the <b>Census 2011</b>, Christians numbered about <b>2.78 crore (27.8 million)</b>, forming <b>2.3 per cent</b> of India's population. They are the <b>third-largest religious community</b> after Hindus and Muslims.<br><br><br><b><u>Important Points:</u></b><br>• Hindus formed <b>79.8 per cent</b> (96.6 crore) and Muslims <b>14.2 per cent</b> (17.2 crore) of the population in 2011.<br>• Sikhs numbered <b>2.08 crore (1.7 per cent)</b> and Buddhists 0.84 crore (0.7 per cent), from which the figures in the other options are taken.<br>• The Census 2011 was the <b>15th national census</b> since 1872 and the <b>7th after Independence</b>, with the slogan <b>Our Census, Our Future</b>.<br>• The population of India in 2011 was <b>121.09 crore</b>, with a decadal growth of 17.7 per cent and a density of 382 persons per sq km.","hi":"<b>सही उत्तर: विकल्प (2) – 27.8 मिलियन तथा 2.3%</b><br><b>जनगणना 2011</b> के अनुसार ईसाइयों की संख्या लगभग <b>2.78 करोड़ (27.8 मिलियन)</b> थी, जो भारत की जनसंख्या का <b>2.3 प्रतिशत</b> है। हिंदू व मुस्लिमों के बाद यह <b>तीसरा सबसे बड़ा धार्मिक समुदाय</b> है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• 2011 में हिंदू जनसंख्या का <b>79.8 प्रतिशत</b> (96.6 करोड़) तथा मुस्लिम <b>14.2 प्रतिशत</b> (17.2 करोड़) थे।<br>• सिख <b>2.08 करोड़ (1.7 प्रतिशत)</b> तथा बौद्ध 0.84 करोड़ (0.7 प्रतिशत) थे; शेष विकल्पों के आँकड़े इन्हीं से लिए गए हैं।<br>• जनगणना 2011 1872 के बाद <b>15वीं राष्ट्रीय जनगणना</b> तथा स्वतंत्रता के बाद <b>7वीं जनगणना</b> थी, जिसका नारा <b>हमारी जनगणना, हमारा भविष्य</b> था।<br>• 2011 में भारत की जनसंख्या <b>121.09 करोड़</b>, दशकीय वृद्धि 17.7 प्रतिशत तथा जनघनत्व 382 व्यक्ति प्रति वर्ग किमी था।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":44,"local_id":"50044","quid":"Q1000072524","section":"GK","topic":"Ancient History: Miscellaneous","question":{"en":"Consider the following statements regarding Indian temple architecture:<br>1. Nagara-style temples usually have a curvilinear Shikhara.<br>2. The Garbhagriha always lies directly below the tallest tower.<br>Which of the statements given above is/are <b>correct</b>? [SSC CGL 14/10/26 Shift 3]","hi":"भारतीय मंदिर स्थापत्य के संबंध में निम्नलिखित कथनों पर विचार कीजिए:<br>1. नागर शैली के मंदिरों में सामान्यतः वक्ररेखीय शिखर होता है।<br>2. गर्भगृह सदैव सबसे ऊँचे शिखर के ठीक नीचे स्थित होता है।<br>उपर्युक्त कथनों में से कौन-सा/से <b>सही</b> है/हैं? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"1 only","hi":"केवल 1"},"2":{"en":"2 only","hi":"केवल 2"},"3":{"en":"Both 1 and 2","hi":"1 और 2 दोनों"},"4":{"en":"Neither 1 nor 2","hi":"न तो 1, न ही 2"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Both 1 and 2</b><br>Nagara temples are distinguished by a <b>curvilinear shikhara</b> rising above the sanctum, and the <b>Garbhagriha</b>, which houses the main deity, lies directly beneath the <b>tallest tower</b> of the temple. Both statements are correct.<br><br><br><b><u>Important Points:</u></b><br>• In <b>Nagara</b> style the shikhara is curvilinear and topped by an <b>amalaka and kalasha</b>; in <b>Dravida</b> style it is a pyramidal <b>vimana</b> with a gopuram gateway.<br>• The <b>Garbhagriha</b> is a small, dark chamber entered from the mandapa, and the <b>pradakshina patha</b> around it allows circumambulation.<br>• Nagara temples are classed by their shikhara as <b>Latina, Phamsana and Valabhi</b>, and the temples of <b>Khajuraho and Konark</b> are well-known examples.<br>• The <b>Nagara, Dravida and Vesara</b> are the three main styles described in the Shilpa Shastras, and the <b>Kailasanatha temple at Ellora</b> shows a mixed form.","hi":"<b>सही उत्तर: विकल्प (3) – 1 और 2 दोनों</b><br>नागर मंदिर <b>वक्ररेखीय शिखर</b> के लिए पहचाने जाते हैं, जो गर्भगृह के ऊपर उठता है, तथा मुख्य देवता वाला <b>गर्भगृह</b> मंदिर के <b>सबसे ऊँचे शिखर</b> के ठीक नीचे स्थित होता है। अतः दोनों कथन सही हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>नागर</b> शैली में शिखर वक्ररेखीय होता है और उसके शीर्ष पर <b>आमलक व कलश</b> होते हैं; <b>द्रविड़</b> शैली में यह पिरामिडाकार <b>विमान</b> तथा गोपुरम द्वार होता है।<br>• <b>गर्भगृह</b> एक छोटा, अंधकारमय कक्ष होता है जिसमें मंडप से प्रवेश होता है, तथा इसके चारों ओर <b>प्रदक्षिणा पथ</b> परिक्रमा हेतु होता है।<br>• नागर मंदिर अपने शिखर के आधार पर <b>लतिना, फमसना व वलभी</b> प्रकार के होते हैं; <b>खजुराहो व कोणार्क</b> के मंदिर इसके प्रसिद्ध उदाहरण हैं।<br>• शिल्प शास्त्रों में <b>नागर, द्रविड़ व वेसर</b> तीन प्रमुख शैलियाँ बताई गई हैं; <b>एलोरा का कैलासनाथ मंदिर</b> मिश्रित रूप दर्शाता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":45,"local_id":"50045","quid":"Q1000072525","section":"GK","topic":"Science and Technology: Science and Technology","question":{"en":"Which of the following propellant combinations is used by ISRO's Semicryogenic Engine (SE2000)? [SSC CGL 14/10/26 Shift 3]","hi":"निम्नलिखित में से कौन-सा प्रणोदक संयोजन इसरो के अर्ध-क्रायोजेनिक इंजन (SE2000) में प्रयुक्त होता है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Liquid Hydrogen and Liquid Oxygen","hi":"द्रव हाइड्रोजन तथा द्रव ऑक्सीजन"},"2":{"en":"Hydrazine and Nitrogen Tetroxide","hi":"हाइड्राज़ीन तथा नाइट्रोजन टेट्रोक्साइड"},"3":{"en":"Liquid Oxygen and Kerosene","hi":"द्रव ऑक्सीजन तथा मिट्टी का तेल (केरोसीन)"},"4":{"en":"Methane and Liquid Oxygen","hi":"मीथेन तथा द्रव ऑक्सीजन"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Liquid Oxygen and Kerosene</b><br>ISRO's <b>Semicryogenic Engine SE2000</b> uses <b>liquid oxygen as the oxidiser and kerosene as the fuel</b>. A semi-cryogenic engine combines a cryogenic oxidiser with a non-cryogenic hydrocarbon fuel.<br><br><br><b><u>Important Points:</u></b><br>• The SE2000 develops about <b>2,000 kN of thrust</b> and is being developed for the booster stage of future heavy-lift launch vehicles.<br>• <b>Liquid hydrogen and liquid oxygen</b> are the propellants of fully cryogenic engines such as the <b>CE-20</b> engine of the LVM3.<br>• <b>Hydrazine and nitrogen tetroxide</b> are hypergolic propellants used in the L110 core stage of the GSLV and the second stage of the PSLV.<br>• Kerosene is preferred for its low cost, storability at ambient temperature and higher density than liquid hydrogen.","hi":"<b>सही उत्तर: विकल्प (3) – द्रव ऑक्सीजन तथा मिट्टी का तेल (केरोसीन)</b><br>इसरो के <b>अर्ध-क्रायोजेनिक इंजन SE2000</b> में <b>द्रव ऑक्सीजन ऑक्सीकारक तथा केरोसीन ईंधन</b> के रूप में प्रयुक्त होते हैं। अर्ध-क्रायोजेनिक इंजन में क्रायोजेनिक ऑक्सीकारक के साथ गैर-क्रायोजेनिक हाइड्रोकार्बन ईंधन प्रयुक्त होता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• SE2000 लगभग <b>2,000 किलोन्यूटन प्रणोद</b> उत्पन्न करता है और इसे भविष्य के भारी प्रक्षेपण यानों के बूस्टर चरण हेतु विकसित किया जा रहा है।<br>• <b>द्रव हाइड्रोजन तथा द्रव ऑक्सीजन</b> पूर्ण क्रायोजेनिक इंजनों के प्रणोदक हैं, जैसे LVM3 के <b>CE-20</b> इंजन में।<br>• <b>हाइड्राज़ीन तथा नाइट्रोजन टेट्रोक्साइड</b> हाइपरगोलिक प्रणोदक हैं, जो GSLV के L110 कोर चरण तथा PSLV के द्वितीय चरण में प्रयुक्त होते हैं।<br>• केरोसीन कम लागत, सामान्य तापमान पर भंडारणीयता तथा द्रव हाइड्रोजन की तुलना में अधिक घनत्व के कारण पसंद किया जाता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":46,"local_id":"50046","quid":"Q1000072526","section":"GK","topic":"Economics: 1991 Reforms And Industrial policy","question":{"en":"The improvement in food demand after the 1991 reforms was mainly attributed to: [SSC CGL 14/10/26 Shift 3]","hi":"1991 के सुधारों के बाद खाद्य माँग में हुए सुधार का मुख्य कारण था: [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Higher economic growth","hi":"उच्च आर्थिक वृद्धि"},"2":{"en":"Increased farm subsidies","hi":"कृषि सब्सिडी में वृद्धि"},"3":{"en":"Higher import duties","hi":"उच्च आयात शुल्क"},"4":{"en":"Expanded irrigation","hi":"सिंचाई का विस्तार"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Higher economic growth</b><br>After the <b>1991 reforms</b> the growth of the economy accelerated, raising <b>incomes, employment and purchasing power</b>, and this higher economic growth was the main reason for the improvement in <b>food demand</b>.<br><br><br><b><u>Important Points:</u></b><br>• The 1991 reforms deregulated industry, opened the economy to foreign trade and investment, and produced a sustained rise in GDP growth in the 1990s and 2000s.<br>• With rising incomes the demand for <b>processed and high-value foods</b> such as milk, fruits, vegetables and meat increased, a shift described as the dietary transition.<br>• <b>Farm subsidies</b> and <b>irrigation</b> affect the supply of food, not its demand, while higher import duties raise prices and reduce demand.<br>• The <b>economic liberalisation of 1991</b> also reduced the licence-permit system and devalued the rupee to boost exports.","hi":"<b>सही उत्तर: विकल्प (1) – उच्च आर्थिक वृद्धि</b><br><b>1991 के सुधारों</b> के बाद अर्थव्यवस्था की वृद्धि तेज हुई, जिससे <b>आय, रोजगार तथा क्रय शक्ति</b> बढ़ी; यही उच्च आर्थिक वृद्धि <b>खाद्य माँग</b> में सुधार का मुख्य कारण थी।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• 1991 के सुधारों ने उद्योग का नियंत्रणमुक्त किया, अर्थव्यवस्था को विदेशी व्यापार व निवेश हेतु खोला तथा 1990 व 2000 के दशक में GDP वृद्धि में सतत बढ़ोतरी की।<br>• आय बढ़ने से दूध, फल, सब्जी व मांस जैसे <b>प्रसंस्कृत व उच्च मूल्य के खाद्य पदार्थों</b> की माँग बढ़ी, जिसे आहार संक्रमण कहा जाता है।<br>• <b>कृषि सब्सिडी</b> तथा <b>सिंचाई</b> खाद्य की पूर्ति को प्रभावित करते हैं, माँग को नहीं, जबकि अधिक आयात शुल्क कीमतें बढ़ाकर माँग घटाते हैं।<br>• <b>1991 के आर्थिक उदारीकरण</b> ने लाइसेंस-परमिट व्यवस्था घटाई तथा निर्यात बढ़ाने हेतु रुपये का अवमूल्यन किया।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":47,"local_id":"50047","quid":"Q1000072527","section":"GK","topic":"Ancient History: Jainism and Buddhism","question":{"en":"The Jataka stories, which narrate the previous lives of the Buddha, are included in which Pitaka of the Pali Canon? [SSC CGL 14/10/26 Shift 3]","hi":"बुद्ध के पूर्व जन्मों का वर्णन करने वाली जातक कथाएँ पालि त्रिपिटक के किस पिटक में सम्मिलित हैं? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Vinaya Pitaka","hi":"विनय पिटक"},"2":{"en":"Sutta Pitaka","hi":"सुत्त पिटक"},"3":{"en":"Abhidhamma Pitaka","hi":"अभिधम्म पिटक"},"4":{"en":"Jataka Pitaka","hi":"जातक पिटक"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Sutta Pitaka</b><br>The <b>Jataka tales</b>, which narrate the <b>previous births of the Buddha</b>, form part of the <b>Khuddaka Nikaya</b> of the <b>Sutta Pitaka</b> in the Pali Tipitaka. There is no separate Jataka Pitaka.<br><br><br><b><u>Important Points:</u></b><br>• The Pali canon has three Pitakas - <b>Vinaya Pitaka</b> (rules of the monastic order), <b>Sutta Pitaka</b> (sermons of the Buddha) and <b>Abhidhamma Pitaka</b> (philosophical analysis).<br>• The Sutta Pitaka has five Nikayas - <b>Digha, Majjhima, Samyutta, Anguttara and Khuddaka</b> - and the Khuddaka Nikaya contains the Jataka, the Dhammapada and the Therigatha.<br>• The <b>Jataka</b> stories were carved in relief at <b>Sanchi, Bharhut and Amaravati</b> and give vivid pictures of ancient Indian social life.<br>• The Tipitaka was compiled at the <b>First Buddhist Council at Rajgir</b> and was later written down in the Pali language.","hi":"<b>सही उत्तर: विकल्प (2) – सुत्त पिटक</b><br><b>बुद्ध के पूर्व जन्मों</b> का वर्णन करने वाली <b>जातक कथाएँ</b> पालि त्रिपिटक के <b>सुत्त पिटक</b> की <b>खुद्दक निकाय</b> का भाग हैं। जातक नाम का कोई पृथक पिटक नहीं है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• पालि त्रिपिटक में तीन पिटक हैं - <b>विनय पिटक</b> (भिक्षु संघ के नियम), <b>सुत्त पिटक</b> (बुद्ध के उपदेश) तथा <b>अभिधम्म पिटक</b> (दार्शनिक विश्लेषण)।<br>• सुत्त पिटक में पाँच निकाय हैं - <b>दीघ, मज्झिम, संयुत्त, अंगुत्तर तथा खुद्दक</b>; खुद्दक निकाय में जातक, धम्मपद व थेरीगाथा सम्मिलित हैं।<br>• <b>जातक</b> कथाएँ <b>साँची, भरहुत व अमरावती</b> में उत्कीर्ण हैं और प्राचीन भारतीय सामाजिक जीवन का सजीव चित्रण करती हैं।<br>• त्रिपिटक का संकलन <b>राजगृह की प्रथम बौद्ध संगीति</b> में हुआ और बाद में इसे पालि भाषा में लिखित रूप दिया गया।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":48,"local_id":"50048","quid":"Q1000072528","section":"GK","topic":"Economics: Reports and Indices","question":{"en":"Which indicator is used to measure the standard-of-living dimension of the Human Development Index (HDI)? [SSC CGL 14/10/26 Shift 3]","hi":"मानव विकास सूचकांक (HDI) के जीवन-स्तर आयाम के मापन हेतु कौन-सा संकेतक प्रयुक्त होता है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Gross National Income (GNI) per capita Purchasing Power Parity (PPP)","hi":"क्रय शक्ति समता (PPP) पर प्रति व्यक्ति सकल राष्ट्रीय आय (GNI)"},"2":{"en":"Gross Domestic Product (GDP) per capita Purchasing Power Parity (PPP)","hi":"क्रय शक्ति समता (PPP) पर प्रति व्यक्ति सकल घरेलू उत्पाद (GDP)"},"3":{"en":"Net National Product (NNP) per capita Purchasing Power Parity (PPP)","hi":"क्रय शक्ति समता (PPP) पर प्रति व्यक्ति शुद्ध राष्ट्रीय उत्पाद (NNP)"},"4":{"en":"Disposable income per capita Purchasing Power Parity (PPP)","hi":"क्रय शक्ति समता (PPP) पर प्रति व्यक्ति प्रयोज्य आय"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Gross National Income (GNI) per capita Purchasing Power Parity (PPP)</b><br>The <b>standard of living</b> dimension of the HDI is measured by <b>GNI per capita at purchasing power parity</b>, expressed in constant international dollars.<br><br><br><b><u>Important Points:</u></b><br>• The HDI has <b>three dimensions</b> - a long and healthy life (life expectancy at birth), knowledge (expected and mean years of schooling) and a decent standard of living (GNI per capita PPP).<br>• The HDI is published by the <b>United Nations Development Programme</b> in its <b>Human Development Report</b>, and was devised by <b>Mahbub ul Haq and Amartya Sen</b> in 1990.<br>• India ranked <b>130th out of 193 countries</b> in the Human Development Report released in 2025, with an HDI value of about 0.685.<br>• Other UNDP indices include the <b>Inequality-adjusted HDI, Gender Development Index, Gender Inequality Index and Multidimensional Poverty Index</b>.","hi":"<b>सही उत्तर: विकल्प (1) – क्रय शक्ति समता (PPP) पर प्रति व्यक्ति सकल राष्ट्रीय आय (GNI)</b><br>HDI के <b>जीवन-स्तर</b> आयाम का मापन <b>क्रय शक्ति समता पर प्रति व्यक्ति GNI</b> से होता है, जिसे स्थिर अंतर्राष्ट्रीय डॉलर में व्यक्त किया जाता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• HDI के <b>तीन आयाम</b> हैं - दीर्घ व स्वस्थ जीवन (जन्म पर जीवन प्रत्याशा), ज्ञान (अपेक्षित व औसत स्कूली वर्ष) तथा उचित जीवन-स्तर (प्रति व्यक्ति GNI PPP)।<br>• HDI <b>संयुक्त राष्ट्र विकास कार्यक्रम</b> द्वारा <b>मानव विकास रिपोर्ट</b> में प्रकाशित होता है और इसे 1990 में <b>महबूब उल हक तथा अमर्त्य सेन</b> ने विकसित किया।<br>• 2025 में जारी मानव विकास रिपोर्ट में भारत <b>193 देशों में 130वें स्थान</b> पर रहा, जिसका HDI मान लगभग 0.685 था।<br>• UNDP के अन्य सूचकांकों में <b>असमानता-समायोजित HDI, लैंगिक विकास सूचकांक, लैंगिक असमानता सूचकांक तथा बहुआयामी गरीबी सूचकांक</b> सम्मिलित हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":49,"local_id":"50049","quid":"Q1000072529","section":"GK","topic":"Modern History: CDM and Simon Commission","question":{"en":"Under the Communal Award, what electoral right was granted to the Depressed Classes? [SSC CGL 14/10/26 Shift 3]","hi":"सांप्रदायिक निर्णय (Communal Award) के अंतर्गत दलित वर्गों को कौन-सा निर्वाचन अधिकार प्रदान किया गया? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Contest local and provincial elections","hi":"स्थानीय एवं प्रांतीय चुनाव लड़ना"},"2":{"en":"Vote in separate and general electorates","hi":"पृथक तथा सामान्य निर्वाचन मंडलों में मतदान"},"3":{"en":"Form separate provinces and administrative regions","hi":"पृथक प्रांत एवं प्रशासनिक क्षेत्र बनाना"},"4":{"en":"Boycott legislatures and elections","hi":"विधानमंडलों एवं चुनावों का बहिष्कार"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Vote in separate and general electorates</b><br>Under the <b>Communal Award</b> announced by British Prime Minister <b>Ramsay MacDonald in August 1932</b>, the Depressed Classes were given the right to <b>vote in separate electorates</b> as well as in the general electorates.<br><br><br><b><u>Important Points:</u></b><br>• Gandhi opposed separate electorates for the Depressed Classes and began a <b>fast unto death</b> in Yerwada Jail, which led to the <b>Poona Pact of 24 September 1932</b> with Ambedkar.<br>• Under the Poona Pact separate electorates were dropped and the number of <b>reserved seats</b> for the Depressed Classes in the provincial legislatures was increased.<br>• The Communal Award also provided separate electorates for Muslims, Sikhs, Indian Christians, Anglo-Indians and Europeans.<br>• The <b>Government of India Act, 1935</b> later gave legal shape to these arrangements and extended separate electorates to the provinces.","hi":"<b>सही उत्तर: विकल्प (2) – पृथक तथा सामान्य निर्वाचन मंडलों में मतदान</b><br>ब्रिटिश प्रधानमंत्री <b>रैम्जे मैकडोनाल्ड</b> द्वारा <b>अगस्त 1932</b> में घोषित <b>सांप्रदायिक निर्णय</b> के अंतर्गत दलित वर्गों को <b>पृथक निर्वाचन मंडल</b> तथा सामान्य निर्वाचन मंडल दोनों में मतदान का अधिकार दिया गया।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• गांधीजी ने दलित वर्गों हेतु पृथक निर्वाचन मंडल का विरोध किया और यरवदा जेल में <b>आमरण उपवास</b> आरंभ किया, जिसके परिणामस्वरूप अंबेडकर के साथ <b>24 सितंबर 1932 की पूना संधि</b> हुई।<br>• पूना संधि में पृथक निर्वाचन मंडल समाप्त कर दिए गए तथा प्रांतीय विधानमंडलों में दलित वर्गों हेतु <b>आरक्षित सीटों</b> की संख्या बढ़ाई गई।<br>• सांप्रदायिक निर्णय में मुस्लिमों, सिखों, भारतीय ईसाइयों, आंग्ल-भारतीयों तथा यूरोपीय लोगों हेतु भी पृथक निर्वाचन मंडल दिए गए।<br>• <b>भारत सरकार अधिनियम, 1935</b> ने बाद में इन व्यवस्थाओं को कानूनी रूप दिया तथा प्रांतों में पृथक निर्वाचन मंडल विस्तारित किए।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":50,"local_id":"50050","quid":"Q1000072530","section":"GK","topic":"Biology: Diseases","question":{"en":"A village community uses contaminated pond water for drinking and other daily activities. After a few days, many residents develop severe diarrhoea and vomiting. Which disease is most likely spreading through the contaminated water? [SSC CGL 14/10/26 Shift 3]","hi":"किसी ग्राम समुदाय के लोग पीने तथा अन्य दैनिक कार्यों हेतु दूषित तालाब के पानी का उपयोग करते हैं। कुछ दिनों बाद अनेक निवासियों में तीव्र अतिसार एवं उल्टी होने लगती है। दूषित जल से सर्वाधिक संभावित रूप से कौन-सा रोग फैल रहा है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Malaria","hi":"मलेरिया"},"2":{"en":"Cholera","hi":"हैजा"},"3":{"en":"Tuberculosis","hi":"तपेदिक"},"4":{"en":"Rabies","hi":"रेबीज़"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Cholera</b><br><b>Cholera</b> is a waterborne disease caused by the bacterium <b>Vibrio cholerae</b>, and it spreads through contaminated water and food, producing <b>profuse watery diarrhoea and vomiting</b> with rapid dehydration.<br><br><br><b><u>Important Points:</u></b><br>• Cholera spreads by the <b>faecal-oral route</b> through contaminated water, food and unwashed hands; treatment is immediate <b>oral rehydration solution</b> and, in severe cases, intravenous fluids.<br>• <b>Malaria</b> spreads by the bite of an infected female <b>Anopheles mosquito</b>, <b>tuberculosis</b> through droplets in the air by <b>Mycobacterium tuberculosis</b>, and <b>rabies</b> through the bite of an infected animal.<br>• Other waterborne diseases are typhoid, dysentery, jaundice due to hepatitis A and E, and guinea worm disease.<br>• Safe drinking water, sanitation and hand hygiene are the main preventive measures, and India's <b>Jal Jeevan Mission</b> and Swachh Bharat Mission work on them.","hi":"<b>सही उत्तर: विकल्प (2) – हैजा</b><br><b>हैजा</b> <b>विब्रियो कोलेरी</b> नामक जीवाणु से होने वाला जलजनित रोग है, जो दूषित जल व भोजन से फैलता है तथा <b>अत्यधिक पतले दस्त व उल्टी</b> के साथ तीव्र निर्जलीकरण करता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• हैजा दूषित जल, भोजन व अस्वच्छ हाथों के माध्यम से <b>मल-मुख मार्ग</b> से फैलता है; उपचार में तुरंत <b>मौखिक पुनर्जलीकरण घोल</b> तथा गंभीर स्थिति में नसों द्वारा तरल दिया जाता है।<br>• <b>मलेरिया</b> संक्रमित मादा <b>एनोफिलीज मच्छर</b> के काटने से, <b>तपेदिक</b> <b>माइकोबैक्टीरियम ट्यूबरकुलोसिस</b> के हवा में फैले बूँदों से तथा <b>रेबीज़</b> संक्रमित पशु के काटने से फैलता है।<br>• अन्य जलजनित रोग टाइफाइड, पेचिश, हेपेटाइटिस A व E से होने वाला पीलिया तथा गिनी वर्म रोग हैं।<br>• सुरक्षित पेयजल, स्वच्छता व हाथ की स्वच्छता मुख्य निवारक उपाय हैं, जिन पर भारत का <b>जल जीवन मिशन</b> तथा स्वच्छ भारत मिशन कार्य करते हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false}]},"MATH":{"seconds":900,"questions":[{"no":51,"local_id":"50051","quid":"Q1000072531","section":"MATH","topic":"Mensuration (3D)","question":{"en":"The cost of whitewashing a sphere is Rs. 1232 at a rate of Rs. 2 per cm². What is the volume of the sphere? [SSC CGL 14/10/26 Shift 3]","hi":"Rs. 2 प्रति cm² की दर से एक गोले पर सफेदी कराने की लागत Rs. 1232 है। गोले का आयतन क्या है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"\\(\\frac{1342}{3}\\) cm³"},"2":{"en":"\\(\\frac{2342}{3}\\) cm³"},"3":{"en":"\\(\\frac{3412}{3}\\) cm³"},"4":{"en":"\\(\\frac{4312}{3}\\) cm³"}},"answer":"4","solution":{"en":"<svg width=\"135\" height=\"125\" viewBox=\"0 0 135 125\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><circle cx=\"65\" cy=\"65\" r=\"50\"/><path d=\"M15 65a50 12 0 0 0 100 0\"/><path stroke-dasharray=\"4 3\" d=\"M15 65a50 12 0 0 1 100 0M65 65H115\"/><circle cx=\"65\" cy=\"65\" r=\"1.5\" fill=\"#000\"/><g fill=\"#000\" stroke=\"none\"><text x=\"84\" y=\"61\">r</text></g></svg><br>Surface area = \\(\\frac{1232}{2} = 616 = 4\\pi r^2\\)<br>\\(r^2 = \\frac{616 \\times 7}{88} = 49 \\Rightarrow r = 7\\) cm<br>Volume = \\(\\frac{4}{3} \\times \\frac{22}{7} \\times 343 = \\boxed{\\frac{4312}{3}}\\) cm³<br><br><b>Hence, the correct answer is option (4): \\(\\frac{4312}{3}\\) cm³.</b>","hi":"<svg width=\"135\" height=\"125\" viewBox=\"0 0 135 125\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><circle cx=\"65\" cy=\"65\" r=\"50\"/><path d=\"M15 65a50 12 0 0 0 100 0\"/><path stroke-dasharray=\"4 3\" d=\"M15 65a50 12 0 0 1 100 0M65 65H115\"/><circle cx=\"65\" cy=\"65\" r=\"1.5\" fill=\"#000\"/><g fill=\"#000\" stroke=\"none\"><text x=\"84\" y=\"61\">r</text></g></svg><br>पृष्ठीय क्षेत्रफल = \\(\\frac{1232}{2} = 616 = 4\\pi r^2\\)<br>\\(r^2 = \\frac{616 \\times 7}{88} = 49 \\Rightarrow r = 7\\) cm<br>आयतन = \\(\\frac{4}{3} \\times \\frac{22}{7} \\times 343 = \\boxed{\\frac{4312}{3}}\\) cm³<br><br><b>अतः सही उत्तर विकल्प (4): \\(\\frac{4312}{3}\\) cm³ है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":52,"local_id":"50052","quid":"Q1000072532","section":"MATH","topic":"Geometry","question":{"en":"If each interior angle of a regular polygon is 11 times its exterior angle, how many sides does the polygon have? [SSC CGL 14/10/26 Shift 3]","hi":"यदि एक सम बहुभुज का प्रत्येक आंतरिक कोण उसके बाह्य कोण का 11 गुना है, तो बहुभुज की कितनी भुजाएँ हैं? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"26"},"2":{"en":"38"},"3":{"en":"25"},"4":{"en":"24"}},"answer":"4","solution":{"en":"Interior + Exterior = 180° → 11E + E = 180° → E = 15°<br>Number of sides = \\(\\frac{360^\\circ}{15^\\circ} = \\boxed{24}\\)<br><br><b>Hence, the correct answer is option (4): 24.</b>","hi":"आंतरिक + बाह्य = 180° → 11E + E = 180° → E = 15°<br>भुजाओं की संख्या = \\(\\frac{360^\\circ}{15^\\circ} = \\boxed{24}\\)<br><br><b>अतः सही उत्तर विकल्प (4): 24 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":53,"local_id":"50053","quid":"Q1000072533","section":"MATH","topic":"Mensuration (2D)","question":{"en":"A triangular canvas frame has sides 20 m, 21 m, and 29 m. A smaller triangle is drawn inside it by connecting the midpoints of each side. What percentage of the original area is saved if only the inner triangle is used for painting? [SSC CGL 14/10/26 Shift 3]","hi":"एक त्रिभुजाकार कैनवास फ्रेम की भुजाएँ 20 m, 21 m और 29 m हैं। प्रत्येक भुजा के मध्य-बिंदुओं को मिलाकर इसके अंदर एक छोटा त्रिभुज बनाया जाता है। यदि पेंटिंग के लिए केवल भीतरी त्रिभुज का उपयोग किया जाए, तो मूल क्षेत्रफल का कितना प्रतिशत बचता है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"50%"},"2":{"en":"62.50%"},"3":{"en":"75%"},"4":{"en":"87.50%"}},"answer":"3","solution":{"en":"<svg width=\"230\" height=\"222\" viewBox=\"0 0 230 222\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 26L26 196L204 196ZM33 196L33 189L26 189M26 111L115 196L115 111Z\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"20\" y=\"18\">A</text><text x=\"15\" y=\"210\">B</text><text x=\"219\" y=\"206\">C</text><text x=\"16\" y=\"115\">D</text><text x=\"115\" y=\"207\">E</text><text x=\"121\" y=\"111\">F</text><text x=\"20\" y=\"72\" text-anchor=\"end\" font-size=\"11\">20</text><text x=\"165\" y=\"214\" font-size=\"11\">21</text><text x=\"77\" y=\"72\" text-anchor=\"start\" font-size=\"11\">29</text></g></svg><br>Triangle formed by joining midpoints has sides half → area = \\(\\frac{1}{4}\\) of original<br>Area saved = \\(1 - \\frac{1}{4} = \\frac{3}{4}\\)<br>= \\(\\boxed{75\\%}\\)<br><br><b>Hence, the correct answer is option (3): 75%.</b>","hi":"<svg width=\"230\" height=\"222\" viewBox=\"0 0 230 222\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 26L26 196L204 196ZM33 196L33 189L26 189M26 111L115 196L115 111Z\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"20\" y=\"18\">A</text><text x=\"15\" y=\"210\">B</text><text x=\"219\" y=\"206\">C</text><text x=\"16\" y=\"115\">D</text><text x=\"115\" y=\"207\">E</text><text x=\"121\" y=\"111\">F</text><text x=\"20\" y=\"72\" text-anchor=\"end\" font-size=\"11\">20</text><text x=\"165\" y=\"214\" font-size=\"11\">21</text><text x=\"77\" y=\"72\" text-anchor=\"start\" font-size=\"11\">29</text></g></svg><br>मध्य-बिंदुओं को मिलाने से बने त्रिभुज की भुजाएँ आधी → क्षेत्रफल = मूल का \\(\\frac{1}{4}\\)<br>बचा क्षेत्रफल = \\(1 - \\frac{1}{4} = \\frac{3}{4}\\)<br>= \\(\\boxed{75\\%}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 75% है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":54,"local_id":"50054","quid":"Q1000072534","section":"MATH","topic":"Trigonometry","question":{"en":"If sec²A + tan²A = 10, then find sec⁴A − tan⁴A. [SSC CGL 14/10/26 Shift 3]","hi":"यदि sec²A + tan²A = 10 है, तो sec⁴A − tan⁴A ज्ञात कीजिए। [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"1"},"2":{"en":"10"},"3":{"en":"20"},"4":{"en":"25"}},"answer":"2","solution":{"en":"\\(\\sec^4 A - \\tan^4 A = (\\sec^2 A + \\tan^2 A)(\\sec^2 A - \\tan^2 A)\\)<br>\\(\\sec^2 A - \\tan^2 A = 1\\)<br>Value = \\(10 \\times 1 = \\boxed{10}\\)<br><br><b>Hence, the correct answer is option (2): 10.</b>","hi":"\\(\\sec^4 A - \\tan^4 A = (\\sec^2 A + \\tan^2 A)(\\sec^2 A - \\tan^2 A)\\)<br>\\(\\sec^2 A - \\tan^2 A = 1\\)<br>मान = \\(10 \\times 1 = \\boxed{10}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 10 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":55,"local_id":"50055","quid":"Q1000072535","section":"MATH","topic":"Elementary Statistics","question":{"en":"Examine the frequency polygon Comparison of the number of units sold per day for two different products over a month. to answer the following question.<br>What is the modal class (interval with the highest frequency) for Product X and Product Y respectively?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q55.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]","hi":"एक महीने में दो अलग-अलग उत्पादों की प्रतिदिन बिकी इकाइयों की संख्या की तुलना दर्शाने वाले आवृत्ति बहुभुज का अध्ययन करके निम्नलिखित प्रश्न का उत्तर दीजिए।<br>उत्पाद X और उत्पाद Y के लिए बहुलक वर्ग (सबसे अधिक आवृत्ति वाला अंतराल) क्रमशः क्या है?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q55.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Product X: 11–20, Product Y: 31–40","hi":"उत्पाद X: 11–20, उत्पाद Y: 31–40"},"2":{"en":"Product X: 21–30, Product Y: 21–30","hi":"उत्पाद X: 21–30, उत्पाद Y: 21–30"},"3":{"en":"Product X: 21–30, Product Y: 31–40","hi":"उत्पाद X: 21–30, उत्पाद Y: 31–40"},"4":{"en":"Product X: 11–20, Product Y: 21–30","hi":"उत्पाद X: 11–20, उत्पाद Y: 21–30"}},"answer":"2","solution":{"en":"Product X: 5, 10, 15, 5, 0 → highest 15 in 21–30<br>Product Y: 5, 5, 15, 10, 5 → highest 15 in 21–30<br>\\(\\boxed{21\\text{–}30,\\ 21\\text{–}30}\\)<br><br><b>Hence, the correct answer is option (2): Product X: 21–30, Product Y: 21–30.</b>","hi":"उत्पाद X: 5, 10, 15, 5, 0 → सबसे अधिक 15, 21–30 में<br>उत्पाद Y: 5, 5, 15, 10, 5 → सबसे अधिक 15, 21–30 में<br>\\(\\boxed{21\\text{–}30,\\ 21\\text{–}30}\\)<br><br><b>अतः सही उत्तर विकल्प (2): उत्पाद X: 21–30, उत्पाद Y: 21–30 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q55.jpg"]}},{"no":56,"local_id":"50056","quid":"Q1000072536","section":"MATH","topic":"Data Interpretation (DI)","question":{"en":"Using the provided bar graph, which shows the number of students in each class, answer the following questions.<br>Suppose the average score of students in each class is as follows:<br>Class I – <b>60</b>, Class II – <b>70</b>, Class III – <b>55</b>, Class IV – <b>65</b>, Class V – <b>75</b>.<br>What is the overall average score of all students combined?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q56.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]","hi":"दिए गए दंड आलेख, जो प्रत्येक कक्षा में छात्रों की संख्या दर्शाता है, का उपयोग करके निम्नलिखित प्रश्नों के उत्तर दीजिए।<br>मान लीजिए प्रत्येक कक्षा में छात्रों का औसत अंक इस प्रकार है:<br>कक्षा I – <b>60</b>, कक्षा II – <b>70</b>, कक्षा III – <b>55</b>, कक्षा IV – <b>65</b>, कक्षा V – <b>75</b>।<br>सभी छात्रों का संयुक्त औसत अंक क्या है?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q56.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"65.1"},"2":{"en":"64.6"},"3":{"en":"64.2"},"4":{"en":"63.8"}},"answer":"1","solution":{"en":"Students: 45, 50, 40, 60, 40 → total 235<br>Total score = 45×60 + 50×70 + 40×55 + 60×65 + 40×75 = 2700 + 3500 + 2200 + 3900 + 3000 = 15300<br>Average = \\(\\frac{15300}{235} \\approx \\boxed{65.1}\\)<br><br><b>Hence, the correct answer is option (1): 65.1.</b>","hi":"छात्र: 45, 50, 40, 60, 40 → कुल 235<br>कुल अंक = 45×60 + 50×70 + 40×55 + 60×65 + 40×75 = 2700 + 3500 + 2200 + 3900 + 3000 = 15300<br>औसत = \\(\\frac{15300}{235} \\approx \\boxed{65.1}\\)<br><br><b>अतः सही उत्तर विकल्प (1): 65.1 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q56.jpg"]}},{"no":57,"local_id":"50057","quid":"Q1000072537","section":"MATH","topic":"Data Interpretation (DI)","question":{"en":"Examine the bar graph below to, answer the following question.<br>What is the total fuel consumption (petrol + diesel) for all vehicle types combined, and which vehicle type contributes the least to it?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q57.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]","hi":"नीचे दिए गए दंड आलेख का अध्ययन करके निम्नलिखित प्रश्न का उत्तर दीजिए।<br>सभी प्रकार के वाहनों की कुल ईंधन खपत (पेट्रोल + डीज़ल) कितनी है, और इसमें कौन-सा वाहन प्रकार सबसे कम योगदान देता है?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q57.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"465 L; Bus","hi":"465 L; बस"},"2":{"en":"465 L; Bike","hi":"465 L; बाइक"},"3":{"en":"470 L; Van","hi":"470 L; वैन"},"4":{"en":"475 L; Bike","hi":"475 L; बाइक"}},"answer":"2","solution":{"en":"Petrol + Diesel: Car 45 + 60 = 105, Bus 10 + 90 = 100, Bike 50 + 5 = 55, Truck 15 + 100 = 115, Van 30 + 60 = 90<br>Total = 465 L; least = Bike (55 L)<br>\\(\\boxed{465 \\text{ L; Bike}}\\)<br><br><b>Hence, the correct answer is option (2): 465 L; Bike.</b>","hi":"पेट्रोल + डीज़ल: कार 45 + 60 = 105, बस 10 + 90 = 100, बाइक 50 + 5 = 55, ट्रक 15 + 100 = 115, वैन 30 + 60 = 90<br>कुल = 465 L; सबसे कम = बाइक (55 L)<br>\\(\\boxed{465 \\text{ L; Bike}}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 465 L; बाइक है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q57.jpg"]}},{"no":58,"local_id":"50058","quid":"Q1000072538","section":"MATH","topic":"Number System","question":{"en":"<b>Find the value of</b> \\(0.4\\overline{7} + 0.5\\overline{8}\\). [SSC CGL 14/10/26 Shift 3]","hi":"<b>मान ज्ञात कीजिए:</b> \\(0.4\\overline{7} + 0.5\\overline{8}\\)। [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"\\(1.0\\overline{5}\\)"},"2":{"en":"\\(2.06\\overline{5}\\)"},"3":{"en":"\\(1.0\\overline{6}\\)"},"4":{"en":"\\(2.0\\overline{6}\\)"}},"answer":"3","solution":{"en":"\\(0.4\\overline{7} = \\frac{47 - 4}{90} = \\frac{43}{90},\\ 0.5\\overline{8} = \\frac{58 - 5}{90} = \\frac{53}{90}\\)<br>Sum = \\(\\frac{96}{90} = 1.0666\\ldots\\)<br>\\(= \\boxed{1.0\\overline{6}}\\)<br><br><b>Hence, the correct answer is option (3): \\(1.0\\overline{6}\\).</b>","hi":"\\(0.4\\overline{7} = \\frac{47 - 4}{90} = \\frac{43}{90},\\ 0.5\\overline{8} = \\frac{58 - 5}{90} = \\frac{53}{90}\\)<br>योग = \\(\\frac{96}{90} = 1.0666\\ldots\\)<br>\\(= \\boxed{1.0\\overline{6}}\\)<br><br><b>अतः सही उत्तर विकल्प (3): \\(1.0\\overline{6}\\) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":59,"local_id":"50059","quid":"Q1000072539","section":"MATH","topic":"Simplification and Approximation","question":{"en":"<b>Simplify:</b> \\(\\frac{\\left(\\frac{1}{0.2}\\right)^3 - \\left(\\frac{1}{0.5}\\right)^3}{\\left(\\frac{1}{0.2}\\right)^2 + \\left(\\frac{1}{0.2 \\times 0.5}\\right) + \\left(\\frac{1}{0.5}\\right)^2}\\). [SSC CGL 14/10/26 Shift 3]","hi":"<b>सरल कीजिए:</b> \\(\\frac{\\left(\\frac{1}{0.2}\\right)^3 - \\left(\\frac{1}{0.5}\\right)^3}{\\left(\\frac{1}{0.2}\\right)^2 + \\left(\\frac{1}{0.2 \\times 0.5}\\right) + \\left(\\frac{1}{0.5}\\right)^2}\\)। [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"1"},"2":{"en":"3"},"3":{"en":"2"},"4":{"en":"4"}},"answer":"2","solution":{"en":"a = \\(\\frac{1}{0.2} = 5\\), b = \\(\\frac{1}{0.5} = 2\\), ab = \\(\\frac{1}{0.2 \\times 0.5} = 10\\)<br>\\(\\frac{a^3 - b^3}{a^2 + ab + b^2} = a - b\\)<br>\\(= 5 - 2 = \\boxed{3}\\)<br><br><b>Hence, the correct answer is option (2): 3.</b>","hi":"a = \\(\\frac{1}{0.2} = 5\\), b = \\(\\frac{1}{0.5} = 2\\), ab = \\(\\frac{1}{0.2 \\times 0.5} = 10\\)<br>\\(\\frac{a^3 - b^3}{a^2 + ab + b^2} = a - b\\)<br>\\(= 5 - 2 = \\boxed{3}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 3 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":60,"local_id":"50060","quid":"Q1000072540","section":"MATH","topic":"Geometry","question":{"en":"An equilateral triangle has an inradius (r) of 5 cm. What is the length of its circumradius (R)? [SSC CGL 14/10/26 Shift 3]","hi":"एक समबाहु त्रिभुज की अंतःत्रिज्या (r) 5 cm है। इसकी परित्रिज्या (R) की लंबाई क्या है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"7 cm"},"2":{"en":"3 cm"},"3":{"en":"10 cm"},"4":{"en":"13 cm"}},"answer":"3","solution":{"en":"<svg width=\"155\" height=\"160\" viewBox=\"0 0 155 160\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><circle cx=\"75\" cy=\"80\" r=\"60\"/><path d=\"M75 20L23 110L127 110Z\"/><path stroke-dasharray=\"4 3\" d=\"M75 80L127 110\"/><circle cx=\"75\" cy=\"80\" r=\"1.5\" fill=\"#000\"/><g fill=\"#000\" stroke=\"none\"><text x=\"75\" y=\"15\" text-anchor=\"middle\">A</text><text x=\"17\" y=\"122\" text-anchor=\"end\">B</text><text x=\"133\" y=\"122\">C</text><text x=\"69\" y=\"78\" text-anchor=\"end\">O</text><text x=\"103\" y=\"91\">R</text><text x=\"75\" y=\"125\" text-anchor=\"middle\">a</text></g></svg><br>In an equilateral triangle, R = 2r (centroid divides the median in 2 : 1)<br>\\(R = 2 \\times 5 = \\boxed{10}\\) cm<br><br><b>Hence, the correct answer is option (3): 10 cm.</b>","hi":"<svg width=\"155\" height=\"160\" viewBox=\"0 0 155 160\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><circle cx=\"75\" cy=\"80\" r=\"60\"/><path d=\"M75 20L23 110L127 110Z\"/><path stroke-dasharray=\"4 3\" d=\"M75 80L127 110\"/><circle cx=\"75\" cy=\"80\" r=\"1.5\" fill=\"#000\"/><g fill=\"#000\" stroke=\"none\"><text x=\"75\" y=\"15\" text-anchor=\"middle\">A</text><text x=\"17\" y=\"122\" text-anchor=\"end\">B</text><text x=\"133\" y=\"122\">C</text><text x=\"69\" y=\"78\" text-anchor=\"end\">O</text><text x=\"103\" y=\"91\">R</text><text x=\"75\" y=\"125\" text-anchor=\"middle\">a</text></g></svg><br>समबाहु त्रिभुज में R = 2r (केन्द्रक माध्यिका को 2 : 1 में बाँटता है)<br>\\(R = 2 \\times 5 = \\boxed{10}\\) cm<br><br><b>अतः सही उत्तर विकल्प (3): 10 cm है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":61,"local_id":"50061","quid":"Q1000072541","section":"MATH","topic":"Number System","question":{"en":"Find the value of x + y if the number 985x3678y is divisible by 72. [SSC CGL 14/10/26 Shift 3]","hi":"यदि संख्या 985x3678y, 72 से विभाज्य है, तो x + y का मान ज्ञात कीजिए। [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"5"},"2":{"en":"12"},"3":{"en":"9"},"4":{"en":"8"}},"answer":"4","solution":{"en":"72 = 8 × 9<br>Divisible by 8: last three digits 78y → 784 ✔ → y = 4<br>Divisible by 9: 9 + 8 + 5 + x + 3 + 6 + 7 + 8 + 4 = 50 + x → x = 4<br>x + y = \\(\\boxed{8}\\)<br><br><b>Hence, the correct answer is option (4): 8.</b>","hi":"72 = 8 × 9<br>8 से विभाज्यता: अंतिम तीन अंक 78y → 784 ✔ → y = 4<br>9 से विभाज्यता: 9 + 8 + 5 + x + 3 + 6 + 7 + 8 + 4 = 50 + x → x = 4<br>x + y = \\(\\boxed{8}\\)<br><br><b>अतः सही उत्तर विकल्प (4): 8 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":62,"local_id":"50062","quid":"Q1000072542","section":"MATH","topic":"Profit and Loss","question":{"en":"An article was sold at a 15% loss. If the selling price had been increased by &#36;30.60, a profit of 9% would have been achieved. Determine the selling price required to achieve a 10% profit. [SSC CGL 14/10/26 Shift 3]","hi":"एक वस्तु 15% हानि पर बेची गई। यदि विक्रय मूल्य &#36;30.60 अधिक होता, तो 9% लाभ होता। 10% लाभ प्राप्त करने के लिए आवश्यक विक्रय मूल्य ज्ञात कीजिए। [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"&#36;180.25"},"2":{"en":"&#36;140.25"},"3":{"en":"&#36;250.25"},"4":{"en":"&#36;280.25"}},"answer":"2","solution":{"en":"From −15% to +9% = 24% of CP = 30.60<br>CP = \\(\\frac{30.60}{24} \\times 100 = 127.50\\)<br>SP for 10% profit = \\(127.50 \\times 1.1 = \\boxed{140.25}\\)<br><br><b>Hence, the correct answer is option (2): &#36;140.25.</b>","hi":"−15% से +9% = क्रय मूल्य का 24% = 30.60<br>क्रय मूल्य = \\(\\frac{30.60}{24} \\times 100 = 127.50\\)<br>10% लाभ के लिए विक्रय मूल्य = \\(127.50 \\times 1.1 = \\boxed{140.25}\\)<br><br><b>अतः सही उत्तर विकल्प (2): &#36;140.25 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":63,"local_id":"50063","quid":"Q1000072543","section":"MATH","topic":"Geometry","question":{"en":"A chord AB of a circle subtends an angle of 70° at a point on the major arc. What is the angle subtended by the same chord at the centre of the circle? [SSC CGL 14/10/26 Shift 3]","hi":"एक वृत्त की जीवा AB दीर्घ चाप पर स्थित एक बिंदु पर 70° का कोण बनाती है। वही जीवा वृत्त के केंद्र पर कितना कोण बनाती है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"35°"},"2":{"en":"70°"},"3":{"en":"125°"},"4":{"en":"140°"}},"answer":"4","solution":{"en":"<svg width=\"165\" height=\"150\" viewBox=\"0 0 165 150\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><circle cx=\"80\" cy=\"75\" r=\"55\"/><path d=\"M28 94L80 20L132 94ZM28 94L80 75L132 94\"/><circle cx=\"80\" cy=\"75\" r=\"1.5\" fill=\"#000\"/><g fill=\"#000\" stroke=\"none\"><text x=\"74\" y=\"73\" text-anchor=\"end\">O</text><text x=\"24\" y=\"106\" text-anchor=\"end\">A</text><text x=\"136\" y=\"106\">B</text><text x=\"80\" y=\"15\" text-anchor=\"middle\">P</text><text x=\"80\" y=\"46\" text-anchor=\"middle\">70°</text><text x=\"80\" y=\"97\" text-anchor=\"middle\">?</text></g></svg><br>Angle at the centre = 2 × angle on the major arc<br>\\(\\angle AOB = 2 \\times 70^\\circ = \\boxed{140^\\circ}\\)<br><br><b>Hence, the correct answer is option (4): 140°.</b>","hi":"<svg width=\"165\" height=\"150\" viewBox=\"0 0 165 150\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><circle cx=\"80\" cy=\"75\" r=\"55\"/><path d=\"M28 94L80 20L132 94ZM28 94L80 75L132 94\"/><circle cx=\"80\" cy=\"75\" r=\"1.5\" fill=\"#000\"/><g fill=\"#000\" stroke=\"none\"><text x=\"74\" y=\"73\" text-anchor=\"end\">O</text><text x=\"24\" y=\"106\" text-anchor=\"end\">A</text><text x=\"136\" y=\"106\">B</text><text x=\"80\" y=\"15\" text-anchor=\"middle\">P</text><text x=\"80\" y=\"46\" text-anchor=\"middle\">70°</text><text x=\"80\" y=\"97\" text-anchor=\"middle\">?</text></g></svg><br>केंद्र पर कोण = 2 × दीर्घ चाप पर कोण<br>\\(\\angle AOB = 2 \\times 70^\\circ = \\boxed{140^\\circ}\\)<br><br><b>अतः सही उत्तर विकल्प (4): 140° है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":64,"local_id":"50064","quid":"Q1000072544","section":"MATH","topic":"Height and Distance","question":{"en":"Two observers on the same side of a tower see its top at angles 30° and 45°. The height of the tower is 90 m. Find the approximate distance between them. Take \\((\\sqrt{3} = 1.732)\\) [SSC CGL 14/10/26 Shift 3]","hi":"एक मीनार के एक ही ओर खड़े दो प्रेक्षक उसके शीर्ष को 30° और 45° के कोणों पर देखते हैं। मीनार की ऊँचाई 90 m है। उनके बीच की लगभग दूरी ज्ञात कीजिए। \\((\\sqrt{3} = 1.732)\\) लीजिए। [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"73 m"},"2":{"en":"66 m"},"3":{"en":"60 m"},"4":{"en":"71 m"}},"answer":"2","solution":{"en":"<svg width=\"262\" height=\"159\" viewBox=\"0 0 262 159\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M50 20V124H230ZM50 20L154 124\"/><path d=\"M50 116h8v8\"/><path d=\"M138 124A16 16 0 0 1 143 113\"/><path d=\"M214 124A16 16 0 0 1 216 116\"/><path d=\"M154 143H230\" stroke-width=\"1\"/><g fill=\"#000\" stroke=\"none\"><text x=\"45\" y=\"24\" text-anchor=\"end\">A</text><text x=\"45\" y=\"128\" text-anchor=\"end\">B</text><text x=\"154\" y=\"138\" text-anchor=\"middle\">D</text><text x=\"230\" y=\"138\" text-anchor=\"middle\">C</text><text x=\"45\" y=\"76\" text-anchor=\"end\">90 m</text><text x=\"157\" y=\"118\">45°</text><text x=\"233\" y=\"118\">30°</text><text x=\"192\" y=\"153\" text-anchor=\"middle\">x</text></g></svg><br>BD = 90 m (45°), BC = \\(90\\sqrt{3}\\) m (30°)<br>x = \\(90\\sqrt{3} - 90 = 90 \\times 0.732 = 65.88\\)<br>\\(\\approx \\boxed{66}\\) m<br><br><b>Hence, the correct answer is option (2): 66 m.</b>","hi":"<svg width=\"262\" height=\"159\" viewBox=\"0 0 262 159\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M50 20V124H230ZM50 20L154 124\"/><path d=\"M50 116h8v8\"/><path d=\"M138 124A16 16 0 0 1 143 113\"/><path d=\"M214 124A16 16 0 0 1 216 116\"/><path d=\"M154 143H230\" stroke-width=\"1\"/><g fill=\"#000\" stroke=\"none\"><text x=\"45\" y=\"24\" text-anchor=\"end\">A</text><text x=\"45\" y=\"128\" text-anchor=\"end\">B</text><text x=\"154\" y=\"138\" text-anchor=\"middle\">D</text><text x=\"230\" y=\"138\" text-anchor=\"middle\">C</text><text x=\"45\" y=\"76\" text-anchor=\"end\">90 m</text><text x=\"157\" y=\"118\">45°</text><text x=\"233\" y=\"118\">30°</text><text x=\"192\" y=\"153\" text-anchor=\"middle\">x</text></g></svg><br>BD = 90 m (45°), BC = \\(90\\sqrt{3}\\) m (30°)<br>x = \\(90\\sqrt{3} - 90 = 90 \\times 0.732 = 65.88\\)<br>\\(\\approx \\boxed{66}\\) m<br><br><b>अतः सही उत्तर विकल्प (2): 66 m है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":65,"local_id":"50065","quid":"Q1000072545","section":"MATH","topic":"Mensuration (2D)","question":{"en":"The perimeter of an isosceles trapezium is 58 cm. If the non-parallel sides are each 13 cm and the height is 12 cm, find its area. [SSC CGL 14/10/26 Shift 3]","hi":"एक समद्विबाहु समलंब चतुर्भुज का परिमाप 58 cm है। यदि असमांतर भुजाएँ प्रत्येक 13 cm हैं और ऊँचाई 12 cm है, तो इसका क्षेत्रफल ज्ञात कीजिए। [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"180 cm²"},"2":{"en":"192 cm²"},"3":{"en":"204 cm²"},"4":{"en":"216 cm²"}},"answer":"2","solution":{"en":"<svg width=\"171\" height=\"111\" viewBox=\"0 0 171 111\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M50 15H116L146 87H20Z\"/><path stroke-dasharray=\"4 3\" d=\"M50 15V87\"/><path d=\"M50 80h7v7\"/><g fill=\"#000\" stroke=\"none\"><text x=\"83\" y=\"11\" text-anchor=\"middle\">a</text><text x=\"83\" y=\"102\" text-anchor=\"middle\">b</text><text x=\"54\" y=\"55\">12</text><text x=\"30\" y=\"51\" text-anchor=\"end\">13</text><text x=\"136\" y=\"51\">13</text></g></svg><br>Sum of parallel sides = 58 − 2 × 13 = 32 cm<br>Area = \\(\\frac{1}{2} \\times 32 \\times 12 = \\boxed{192}\\) cm²<br><br><b>Hence, the correct answer is option (2): 192 cm².</b>","hi":"<svg width=\"171\" height=\"111\" viewBox=\"0 0 171 111\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M50 15H116L146 87H20Z\"/><path stroke-dasharray=\"4 3\" d=\"M50 15V87\"/><path d=\"M50 80h7v7\"/><g fill=\"#000\" stroke=\"none\"><text x=\"83\" y=\"11\" text-anchor=\"middle\">a</text><text x=\"83\" y=\"102\" text-anchor=\"middle\">b</text><text x=\"54\" y=\"55\">12</text><text x=\"30\" y=\"51\" text-anchor=\"end\">13</text><text x=\"136\" y=\"51\">13</text></g></svg><br>समांतर भुजाओं का योग = 58 − 2 × 13 = 32 cm<br>क्षेत्रफल = \\(\\frac{1}{2} \\times 32 \\times 12 = \\boxed{192}\\) cm²<br><br><b>अतः सही उत्तर विकल्प (2): 192 cm² है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":66,"local_id":"50066","quid":"Q1000072546","section":"MATH","topic":"Geometry","question":{"en":"A chord of a circle has a length of 12 cm. The angle subtended by the chord at the circumference of the circle is 30°. What is the distance from the centre of the circle to the chord? [SSC CGL 14/10/26 Shift 3]","hi":"एक वृत्त की जीवा की लंबाई 12 cm है। जीवा द्वारा वृत्त की परिधि पर बनाया गया कोण 30° है। वृत्त के केंद्र से जीवा की दूरी क्या है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"3 cm"},"2":{"en":"\\(3\\sqrt{3}\\) cm"},"3":{"en":"6 cm"},"4":{"en":"\\(6\\sqrt{3}\\) cm"}},"answer":"4","solution":{"en":"<svg width=\"232\" height=\"232\" viewBox=\"0 0 232 232\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M71 194L161 194M116 116L116 194M123 194L123 187L116 187\"/><path stroke-dasharray=\"4 3\" d=\"M116 116L161 194\"/><circle cx=\"116\" cy=\"116\" r=\"90\"/><circle cx=\"116\" cy=\"116\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"108\" y=\"110\">O</text><text x=\"64\" y=\"210\">A</text><text x=\"168\" y=\"210\">B</text><text x=\"116\" y=\"210\">M</text><text x=\"111\" y=\"159\" text-anchor=\"end\" font-size=\"11\">d</text><text x=\"138\" y=\"190\" font-size=\"11\">6</text><text x=\"130\" y=\"164\">12</text></g></svg><br>Angle at centre = 2 × 30° = 60° → ΔOAB is equilateral → r = 12 cm<br>\\(d = \\sqrt{12^2 - 6^2} = \\sqrt{108}\\)<br>\\(= \\boxed{6\\sqrt{3}}\\) cm<br><br><b>Hence, the correct answer is option (4): \\(6\\sqrt{3}\\) cm.</b>","hi":"<svg width=\"232\" height=\"232\" viewBox=\"0 0 232 232\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M71 194L161 194M116 116L116 194M123 194L123 187L116 187\"/><path stroke-dasharray=\"4 3\" d=\"M116 116L161 194\"/><circle cx=\"116\" cy=\"116\" r=\"90\"/><circle cx=\"116\" cy=\"116\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"108\" y=\"110\">O</text><text x=\"64\" y=\"210\">A</text><text x=\"168\" y=\"210\">B</text><text x=\"116\" y=\"210\">M</text><text x=\"111\" y=\"159\" text-anchor=\"end\" font-size=\"11\">d</text><text x=\"138\" y=\"190\" font-size=\"11\">6</text><text x=\"130\" y=\"164\">12</text></g></svg><br>केंद्र पर कोण = 2 × 30° = 60° → ΔOAB समबाहु है → r = 12 cm<br>\\(d = \\sqrt{12^2 - 6^2} = \\sqrt{108}\\)<br>\\(= \\boxed{6\\sqrt{3}}\\) cm<br><br><b>अतः सही उत्तर विकल्प (4): \\(6\\sqrt{3}\\) cm है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":67,"local_id":"50067","quid":"Q1000072547","section":"MATH","topic":"Geometry","question":{"en":"It is given that △ABC is congruent to △PQR. In △ABC, AB = 5 cm, ∠A = 80°, and ∠B = 40°. Which of the following options is correct? [SSC CGL 14/10/26 Shift 3]","hi":"दिया गया है कि △ABC, △PQR के सर्वांगसम है। △ABC में, AB = 5 cm, ∠A = 80° और ∠B = 40° है। निम्नलिखित में से कौन-सा विकल्प सही है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"PQ = 5 cm and ∠P = 60°","hi":"PQ = 5 cm और ∠P = 60°"},"2":{"en":"QR = 5 cm and ∠R = 60°","hi":"QR = 5 cm और ∠R = 60°"},"3":{"en":"QR = 5 cm and ∠Q = 60°","hi":"QR = 5 cm और ∠Q = 60°"},"4":{"en":"PQ = 5 cm and ∠R = 60°","hi":"PQ = 5 cm और ∠R = 60°"}},"answer":"4","solution":{"en":"<svg width=\"165\" height=\"124\" viewBox=\"0 0 165 124\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M39 20L25 100H135Z\"/><g fill=\"#000\" stroke=\"none\"><text x=\"39\" y=\"14\" text-anchor=\"middle\">C</text><text x=\"13\" y=\"104\">A</text><text x=\"139\" y=\"104\">B</text><text x=\"51\" y=\"47\" text-anchor=\"middle\">60°</text><text x=\"47\" y=\"90\" text-anchor=\"middle\">80°</text><text x=\"111\" y=\"95\" text-anchor=\"middle\">40°</text><text x=\"80\" y=\"116\" text-anchor=\"middle\">5</text></g></svg>&nbsp; <svg width=\"165\" height=\"124\" viewBox=\"0 0 165 124\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M39 20L25 100H135Z\"/><g fill=\"#000\" stroke=\"none\"><text x=\"39\" y=\"14\" text-anchor=\"middle\">R</text><text x=\"13\" y=\"104\">P</text><text x=\"139\" y=\"104\">Q</text><text x=\"51\" y=\"47\" text-anchor=\"middle\">60°</text><text x=\"47\" y=\"90\" text-anchor=\"middle\">80°</text><text x=\"111\" y=\"95\" text-anchor=\"middle\">40°</text><text x=\"80\" y=\"116\" text-anchor=\"middle\">5</text></g></svg><br>∠C = 180° − 80° − 40° = 60°<br>A ↔ P, B ↔ Q, C ↔ R → PQ = AB = 5 cm and ∠R = ∠C = 60°<br>\\(\\boxed{PQ = 5 \\text{ cm},\\ \\angle R = 60^\\circ}\\)<br><br><b>Hence, the correct answer is option (4): PQ = 5 cm and ∠R = 60°.</b>","hi":"<svg width=\"165\" height=\"124\" viewBox=\"0 0 165 124\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M39 20L25 100H135Z\"/><g fill=\"#000\" stroke=\"none\"><text x=\"39\" y=\"14\" text-anchor=\"middle\">C</text><text x=\"13\" y=\"104\">A</text><text x=\"139\" y=\"104\">B</text><text x=\"51\" y=\"47\" text-anchor=\"middle\">60°</text><text x=\"47\" y=\"90\" text-anchor=\"middle\">80°</text><text x=\"111\" y=\"95\" text-anchor=\"middle\">40°</text><text x=\"80\" y=\"116\" text-anchor=\"middle\">5</text></g></svg>&nbsp; <svg width=\"165\" height=\"124\" viewBox=\"0 0 165 124\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M39 20L25 100H135Z\"/><g fill=\"#000\" stroke=\"none\"><text x=\"39\" y=\"14\" text-anchor=\"middle\">R</text><text x=\"13\" y=\"104\">P</text><text x=\"139\" y=\"104\">Q</text><text x=\"51\" y=\"47\" text-anchor=\"middle\">60°</text><text x=\"47\" y=\"90\" text-anchor=\"middle\">80°</text><text x=\"111\" y=\"95\" text-anchor=\"middle\">40°</text><text x=\"80\" y=\"116\" text-anchor=\"middle\">5</text></g></svg><br>∠C = 180° − 80° − 40° = 60°<br>A ↔ P, B ↔ Q, C ↔ R → PQ = AB = 5 cm और ∠R = ∠C = 60°<br>\\(\\boxed{PQ = 5 \\text{ cm},\\ \\angle R = 60^\\circ}\\)<br><br><b>अतः सही उत्तर विकल्प (4): PQ = 5 cm और ∠R = 60° है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":68,"local_id":"50068","quid":"Q1000072548","section":"MATH","topic":"Geometry","question":{"en":"A circle with centre O has radius 15 cm. D is a point on the circle such that a 24 cm long chord AB is bisected by OD at point C. Find the length of CD (in cm). [SSC CGL 14/10/26 Shift 3]","hi":"केंद्र O वाले एक वृत्त की त्रिज्या 15 cm है। D वृत्त पर एक बिंदु है जिससे 24 cm लंबी जीवा AB को OD बिंदु C पर समद्विभाजित करती है। CD की लंबाई (cm में) ज्ञात कीजिए। [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"3 cm"},"2":{"en":"6 cm"},"3":{"en":"9 cm"},"4":{"en":"12 cm"}},"answer":"2","solution":{"en":"<svg width=\"232\" height=\"232\" viewBox=\"0 0 232 232\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M44 170L188 170M116 116L116 170M123 170L123 163L116 163\"/><path stroke-dasharray=\"4 3\" d=\"M116 116L188 170M116 170L116 206\"/><circle cx=\"116\" cy=\"116\" r=\"90\"/><circle cx=\"116\" cy=\"116\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"108\" y=\"110\">O</text><text x=\"32\" y=\"182\">A</text><text x=\"200\" y=\"182\">B</text><text x=\"116\" y=\"186\">C</text><text x=\"111\" y=\"147\" text-anchor=\"end\" font-size=\"11\">OC</text><text x=\"152\" y=\"186\" font-size=\"11\">12</text><text x=\"146\" y=\"155\">15</text><text x=\"116\" y=\"217\">D</text></g></svg><br>OC ⟂ AB and AC = CB = 12 cm<br>OC = \\(\\sqrt{15^2 - 12^2} = 9\\) cm<br>CD = OD − OC = 15 − 9 = \\(\\boxed{6}\\) cm<br><br><b>Hence, the correct answer is option (2): 6 cm.</b>","hi":"<svg width=\"232\" height=\"232\" viewBox=\"0 0 232 232\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M44 170L188 170M116 116L116 170M123 170L123 163L116 163\"/><path stroke-dasharray=\"4 3\" d=\"M116 116L188 170M116 170L116 206\"/><circle cx=\"116\" cy=\"116\" r=\"90\"/><circle cx=\"116\" cy=\"116\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"108\" y=\"110\">O</text><text x=\"32\" y=\"182\">A</text><text x=\"200\" y=\"182\">B</text><text x=\"116\" y=\"186\">C</text><text x=\"111\" y=\"147\" text-anchor=\"end\" font-size=\"11\">OC</text><text x=\"152\" y=\"186\" font-size=\"11\">12</text><text x=\"146\" y=\"155\">15</text><text x=\"116\" y=\"217\">D</text></g></svg><br>OC ⟂ AB और AC = CB = 12 cm<br>OC = \\(\\sqrt{15^2 - 12^2} = 9\\) cm<br>CD = OD − OC = 15 − 9 = \\(\\boxed{6}\\) cm<br><br><b>अतः सही उत्तर विकल्प (2): 6 cm है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":69,"local_id":"50069","quid":"Q1000072549","section":"MATH","topic":"Mixture and Alligation","question":{"en":"A milkman sells his milk at the cost price but mixes water to earn a 25% profit. What percentage of the final mixture is water? [SSC CGL 14/10/26 Shift 3]","hi":"एक दूधवाला अपना दूध क्रय मूल्य पर बेचता है लेकिन 25% लाभ कमाने के लिए उसमें पानी मिलाता है। अंतिम मिश्रण में कितने प्रतिशत पानी है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"25%"},"2":{"en":"40%"},"3":{"en":"50%"},"4":{"en":"20%"}},"answer":"4","solution":{"en":"Water : Milk = 25 : 100 = 1 : 4<br>Water % = \\(\\frac{1}{5} \\times 100 = \\boxed{20\\%}\\)<br><br><b>Hence, the correct answer is option (4): 20%.</b>","hi":"पानी : दूध = 25 : 100 = 1 : 4<br>पानी % = \\(\\frac{1}{5} \\times 100 = \\boxed{20\\%}\\)<br><br><b>अतः सही उत्तर विकल्प (4): 20% है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":70,"local_id":"50070","quid":"Q1000072550","section":"MATH","topic":"Geometry","question":{"en":"Three circles are drawn on a flat surface. None of the circles touch or cross each other, and none of them are inside one another. What is the maximum number of common tangents (lines that touch the circles at just one point) that can be drawn for all three pairs of circles combined? [SSC CGL 14/10/26 Shift 3]","hi":"एक समतल सतह पर तीन वृत्त बनाए गए हैं। कोई भी वृत्त एक-दूसरे को स्पर्श या प्रतिच्छेद नहीं करता, और कोई भी एक-दूसरे के अंदर नहीं है। तीनों वृत्त-युग्मों के लिए कुल मिलाकर अधिकतम कितनी उभयनिष्ठ स्पर्श रेखाएँ (वृत्तों को केवल एक बिंदु पर स्पर्श करने वाली रेखाएँ) खींची जा सकती हैं? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"16"},"2":{"en":"12"},"3":{"en":"10"},"4":{"en":"14"}},"answer":"2","solution":{"en":"Two separate circles (outside each other) have 4 common tangents (2 direct + 2 transverse)<br>Pairs = \\(^3C_2 = 3\\)<br>Total = \\(3 \\times 4 = \\boxed{12}\\)<br><br><b>Hence, the correct answer is option (2): 12.</b>","hi":"एक-दूसरे के बाहर स्थित दो वृत्तों की 4 उभयनिष्ठ स्पर्श रेखाएँ होती हैं (2 सीधी + 2 अनुप्रस्थ)<br>युग्म = \\(^3C_2 = 3\\)<br>कुल = \\(3 \\times 4 = \\boxed{12}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 12 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":71,"local_id":"50071","quid":"Q1000072551","section":"MATH","topic":"Elementary Statistics","question":{"en":"Read the given histogram carefully which shows daily wages (in ₹) of workers along with the number of workers (frequency) in each class interval and answer the question that follows:<br>Find the probability of selecting a worker whose wage lies in the modal class. (round to two decimal places)<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q71.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]","hi":"दिए गए आयतचित्र को ध्यानपूर्वक पढ़िए, जो श्रमिकों की दैनिक मजदूरी (₹ में) तथा प्रत्येक वर्ग अंतराल में श्रमिकों की संख्या (आवृत्ति) दर्शाता है, और नीचे दिए गए प्रश्न का उत्तर दीजिए:<br>ऐसे श्रमिक को चुनने की प्रायिकता ज्ञात कीजिए जिसकी मजदूरी बहुलक वर्ग में आती है। (दो दशमलव स्थानों तक)<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q71.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"0.14"},"2":{"en":"0.22"},"3":{"en":"0.31"},"4":{"en":"0.43"}},"answer":"2","solution":{"en":"Frequencies: 55, 80, 108, 117, 150, 105, 70 → Total = 685<br>Modal class 190–200 (f = 150)<br>P = \\(\\frac{150}{685} = 0.219 \\approx \\boxed{0.22}\\)<br><br><b>Hence, the correct answer is option (2): 0.22.</b>","hi":"आवृत्तियाँ: 55, 80, 108, 117, 150, 105, 70 → कुल = 685<br>बहुलक वर्ग 190–200 (f = 150)<br>P = \\(\\frac{150}{685} = 0.219 \\approx \\boxed{0.22}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 0.22 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q71.jpg"]}},{"no":72,"local_id":"50072","quid":"Q1000072552","section":"MATH","topic":"Data Interpretation (DI)","question":{"en":"Study the pie chart carefully that shows the percentage distribution of employees across different departments in an organization, namely Engineering, Sales, Marketing, HR, and Operations and answer the question that follows:<br>If one employee is selected at random, what is the probability that the employee works in either HR or Operations?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q72.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]","hi":"पाई चार्ट का ध्यानपूर्वक अध्ययन कीजिए जो एक संगठन के विभिन्न विभागों, अर्थात इंजीनियरिंग, बिक्री, विपणन, HR और ऑपरेशंस, में कर्मचारियों का प्रतिशत वितरण दर्शाता है, और नीचे दिए गए प्रश्न का उत्तर दीजिए:<br>यदि एक कर्मचारी यादृच्छिक रूप से चुना जाए, तो उसके HR या ऑपरेशंस में काम करने की प्रायिकता क्या है?<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q72.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"0.50"},"2":{"en":"0.18"},"3":{"en":"0.25"},"4":{"en":"0.36"}},"answer":"3","solution":{"en":"From the chart: HR = 10%, Operations = 15%<br>P(HR or Operations) = \\(\\frac{10 + 15}{100}\\)<br>\\(= \\boxed{0.25}\\)<br><br><b>Hence, the correct answer is option (3): 0.25.</b>","hi":"चार्ट से: HR = 10%, ऑपरेशंस = 15%<br>P(HR या ऑपरेशंस) = \\(\\frac{10 + 15}{100}\\)<br>\\(= \\boxed{0.25}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 0.25 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q72.jpg"]}},{"no":73,"local_id":"50073","quid":"Q1000072553","section":"MATH","topic":"Data Interpretation (DI)","question":{"en":"The pie chart shows the percentage distribution of different water sources used for irrigation in a region. Study the given pie chart carefully and answer the question that follows.<br>If the total volume of water used from Canals is 14,000 litres more than the volume of water used from Tube Wells, calculate the approximate total combined volume of water used from Tanks and Rainwater Harvesting combined.<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q73.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]","hi":"पाई चार्ट एक क्षेत्र में सिंचाई के लिए उपयोग किए जाने वाले विभिन्न जल स्रोतों का प्रतिशत वितरण दर्शाता है। दिए गए पाई चार्ट का ध्यानपूर्वक अध्ययन कीजिए और नीचे दिए गए प्रश्न का उत्तर दीजिए।<br>यदि नहरों से उपयोग किए गए पानी की कुल मात्रा ट्यूबवेल से उपयोग किए गए पानी की मात्रा से 14,000 लीटर अधिक है, तो टैंकों और वर्षा जल संचयन से उपयोग किए गए पानी की लगभग संयुक्त मात्रा ज्ञात कीजिए।<br><img src=\"https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q73.jpg\" style=\"max-width:100%;height:auto\"> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"31,300 litres","hi":"31,300 लीटर"},"2":{"en":"36,220 litres","hi":"36,220 लीटर"},"3":{"en":"23,333 litres","hi":"23,333 लीटर"},"4":{"en":"26,233 litres","hi":"26,233 लीटर"}},"answer":"3","solution":{"en":"From the chart: Canal 45%, Tube Well 30%, Tank 15%, Rainwater Harvesting 10%<br>45% − 30% = 15% = 14000 L<br>Tank + RWH = 25% = \\(\\frac{14000}{15} \\times 25 \\approx \\boxed{23333}\\) L<br><br><b>Hence, the correct answer is option (3): 23,333 litres.</b>","hi":"चार्ट से: नहर 45%, ट्यूबवेल 30%, टैंक 15%, वर्षा जल संचयन 10%<br>45% − 30% = 15% = 14000 L<br>टैंक + वर्षा जल संचयन = 25% = \\(\\frac{14000}{15} \\times 25 \\approx \\boxed{23333}\\) L<br><br><b>अतः सही उत्तर विकल्प (3): 23,333 लीटर है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":true,"images":{"question":["https://res.cloudinary.com/mc6kb3uo/image/upload/ssc_mock/CGL-14-OCT-2026-SHIFT-3/q73.jpg"]}},{"no":74,"local_id":"50074","quid":"Q1000072554","section":"MATH","topic":"Percentage","question":{"en":"A commercial bakery faces a supply chain shock that increases the market price of organic flour by 25%. The bakery's management decides they can only absorb an absolute increase of 5% on their total procurement expenditure for this raw material. By what percentage must the bakery reduce its consumption volume of organic flour to stay within this strict budget constraint? [SSC CGL 14/10/26 Shift 3]","hi":"एक व्यावसायिक बेकरी को आपूर्ति श्रृंखला के झटके का सामना करना पड़ता है जिससे जैविक आटे का बाज़ार मूल्य 25% बढ़ जाता है। बेकरी का प्रबंधन तय करता है कि वह इस कच्चे माल पर अपने कुल खरीद व्यय में केवल 5% की निरपेक्ष वृद्धि वहन कर सकता है। इस सख्त बजट सीमा में रहने के लिए बेकरी को जैविक आटे की खपत की मात्रा में कितने प्रतिशत की कमी करनी होगी? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"20%"},"2":{"en":"16%"},"3":{"en":"25%"},"4":{"en":"10%"}},"answer":"2","solution":{"en":"Expenditure = Price × Consumption<br>New consumption factor = \\(\\frac{1.05}{1.25} = 0.84\\)<br>Reduction = \\(\\boxed{16\\%}\\)<br><br><b>Hence, the correct answer is option (2): 16%.</b>","hi":"व्यय = मूल्य × खपत<br>नई खपत का गुणक = \\(\\frac{1.05}{1.25} = 0.84\\)<br>कमी = \\(\\boxed{16\\%}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 16% है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":75,"local_id":"50075","quid":"Q1000072555","section":"MATH","topic":"Algebra","question":{"en":"Pranita is an animal-rights activist and houses certain number of dogs, cats and birds in her farm. The total number of heads of all these three species in the farm counts to 79. If the number of birds is 250% of the number of cats and the total number of legs of the three species in the farm (combined) is 236, what is the ratio of the number of cats, birds and dogs respectively? [SSC CGL 14/10/26 Shift 3]","hi":"प्रणिता एक पशु-अधिकार कार्यकर्ता है और अपने फार्म में कुछ कुत्ते, बिल्लियाँ और पक्षी रखती है। फार्म में इन तीनों प्रजातियों के सिरों की कुल संख्या 79 है। यदि पक्षियों की संख्या बिल्लियों की संख्या का 250% है और फार्म में तीनों प्रजातियों के पैरों की कुल संख्या 236 है, तो बिल्लियों, पक्षियों और कुत्तों की संख्या का क्रमशः अनुपात क्या है? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"20:50:9"},"2":{"en":"16:40:23"},"3":{"en":"12:60:7"},"4":{"en":"11:55:13"}},"answer":"2","solution":{"en":"Cats = c, Birds = 2.5c, Dogs = 79 − 3.5c<br>Legs: \\(4c + 2(2.5c) + 4(79 - 3.5c) = 236 \\Rightarrow 316 - 5c = 236\\)<br>c = 16, birds = 40, dogs = 23<br>Cats : Birds : Dogs = \\(\\boxed{16 : 40 : 23}\\)<br><br><b>Hence, the correct answer is option (2): 16:40:23.</b>","hi":"बिल्लियाँ = c, पक्षी = 2.5c, कुत्ते = 79 − 3.5c<br>पैर: \\(4c + 2(2.5c) + 4(79 - 3.5c) = 236 \\Rightarrow 316 - 5c = 236\\)<br>c = 16, पक्षी = 40, कुत्ते = 23<br>बिल्लियाँ : पक्षी : कुत्ते = \\(\\boxed{16 : 40 : 23}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 16:40:23 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false}]},"ENGLISH":{"seconds":900,"questions":[{"no":76,"local_id":"50076","quid":"Q1000072556","section":"ENGLISH","topic":"Direct Indirect (Narration)","question":{"en":"Choose the correct option to complete the sentence in indirect speech.<br>Ruhi says, “I don’t drink coffee.”<br>Ruhi says that she ___ drink coffee. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"didn't"},"2":{"en":"doesn't"},"3":{"en":"hadn't"},"4":{"en":"won't"}},"answer":"2","solution":{"en":"<b>Rule: A present reporting verb does not require backshifting.</b><br>“Says” is present, so “don’t drink” becomes “doesn’t drink” only for third-person agreement.<br>“Didn’t” and “hadn’t” shift to past forms unnecessarily.<br>“Won’t” changes the meaning to future refusal.<br><br><b>Hence, the correct answer is option (2): doesn't.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":77,"local_id":"50077","quid":"Q1000072557","section":"ENGLISH","topic":"Direct Indirect (Narration)","question":{"en":"Choose the correct option to convert the following sentence into indirect speech.<br>Popi said, “I've lived in India for a long time.”<br>Popi said that she ___ in India for a long time. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"has lived"},"2":{"en":"had lived"},"3":{"en":"lived"},"4":{"en":"was living"}},"answer":"2","solution":{"en":"<b>Rule: Present perfect becomes past perfect after “said.”</b><br>“I’ve lived” becomes “she had lived.”<br>“Has lived” retains present perfect; “lived” and “was living” change the aspect.<br>The duration phrase remains unchanged.<br><br><b>Hence, the correct answer is option (2): had lived.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":78,"local_id":"50078","quid":"Q1000072558","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Rearrange the parts of the sentence in the correct order.<br>Traditional folk music<br>P. reflecting historical narratives and local traditions<br>Q. shaping the cultural identity of diverse communities<br>R. while preserving indigenous languages and artistic expressions<br>S. continues to evolve in response to contemporary influences, [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"SPRQ"},"2":{"en":"QPRS"},"3":{"en":"PRSQ"},"4":{"en":"RPQS"}},"answer":"1","solution":{"en":"<b>Order: SPRQ</b><br>S supplies the main predicate: folk music continues to evolve.<br>P explains what its evolving forms reflect.<br>R adds its preservative role, and Q states its effect on cultural identity.<br><br><b>Hence, the correct answer is option (1): SPRQ.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":79,"local_id":"50079","quid":"Q1000072559","section":"ENGLISH","topic":"Spotting Errors","question":{"en":"Identify the error in the sentence.<br>She is a honest leader with integrity. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"a"},"2":{"en":"leader"},"3":{"en":"integrity"},"4":{"en":"honest"}},"answer":"1","solution":{"en":"<b>Rule: Use “an” before a vowel sound.</b><br>“Honest” begins with a silent “h,” so its first sound is a vowel.<br>Correct sentence: “She is <b>an</b> honest leader with integrity.”<br>The erroneous article is “a.”<br><br><b>Hence, the correct answer is option (1): a.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":80,"local_id":"50080","quid":"Q1000072560","section":"ENGLISH","topic":"Idioms and Phrases","question":{"en":"What does the idiom “Rise like a phoenix” mean? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"To recover and become successful after a setback"},"2":{"en":"To disappear without a trace"},"3":{"en":"To remain in the same place without progress"},"4":{"en":"To lose everything permanently"}},"answer":"1","solution":{"en":"<b>Rise like a phoenix (विनाश से पुनः उभरना) = recover strongly after failure or destruction.</b><br>Example: “The company rose like a phoenix after the crisis.”<br>Disappearance, stagnation and permanent loss do not express renewal.<br><br><b>Hence, the correct answer is option (1): To recover and become successful after a setback.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":81,"local_id":"50081","quid":"Q1000072561","section":"ENGLISH","topic":"Fill in the Blanks","question":{"en":"Fill in the blank with the appropriate tense.<br>Were the data ___ earlier, corrective measures could have been implemented. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"analyzed thoroughly"},"2":{"en":"had analyzed thoroughly"},"3":{"en":"were analyzed thoroughly"},"4":{"en":"analyze thoroughly"}},"answer":"1","solution":{"en":"<b>Rule: “Were + subject + past participle” forms an inverted unreal-past passive condition.</b><br>The data did not perform the analysis, so the passive “analyzed thoroughly” is required.<br>“Had analyzed” would be active and lacks an agent; “were analyzed” duplicates “were.”<br>The base form “analyze” cannot complete the passive construction.<br><br><b>Hence, the correct answer is option (1): analyzed thoroughly.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":82,"local_id":"50082","quid":"Q1000072562","section":"ENGLISH","topic":"Idioms and Phrases","question":{"en":"What does the idiom “to smell a rat” mean? [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"To suspect something is wrong"},"2":{"en":"To have a keen sense of smell"},"3":{"en":"To admire someone's intelligence"},"4":{"en":"To clean up a messy situation"}},"answer":"1","solution":{"en":"<b>Smell a rat (कुछ गड़बड़ का संदेह करना) = suspect deceit or wrongdoing.</b><br>Example: “I smelled a rat when his story kept changing.”<br>A keen sense of smell is literal; intelligence and cleaning are unrelated.<br><br><b>Hence, the correct answer is option (1): To suspect something is wrong.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":83,"local_id":"50083","quid":"Q1000072563","section":"ENGLISH","topic":"Homophones and Homonyms","question":{"en":"Choose the most appropriate homonym to fill in the blank.<br>A lovely maiden sat by the stream, weaving tiny wildflowers into her long ___. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"brayed"},"2":{"en":"braid"},"3":{"en":"bread"},"4":{"en":"bred"}},"answer":"2","solution":{"en":"<b>Braid (चोटी) = hair woven into three or more strands.</b><br>Wildflowers are woven into a braid.<br>“Brayed” is the cry of a donkey, “bread” is food, and “bred” is the past of “breed.”<br>Only “braid” fits the context.<br><br><b>Hence, the correct answer is option (2): braid.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":84,"local_id":"50084","quid":"Q1000072564","section":"ENGLISH","topic":"Spelling Check","question":{"en":"Fill in the blank with the correctly spelt word.<br>The environmental impact of the project was assessed using ___ models. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"stocastic"},"2":{"en":"stochastic"},"3":{"en":"stocchastic"},"4":{"en":"stochhastic"}},"answer":"2","solution":{"en":"<b>Stochastic (संयोगवादी) = involving random probability.</b><br>The correct spelling is “stochastic.”<br><b>Stocastic</b> omits “h”; <b>stocchastic</b> doubles “c.”<br><b>Stochhastic</b> doubles “h.”<br><br><b>Hence, the correct answer is option (2): stochastic.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":85,"local_id":"50085","quid":"Q1000072565","section":"ENGLISH","topic":"Antonym","question":{"en":"Select the most appropriate antonym of the given word. <b>Magnanimous</b> [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Noble"},"2":{"en":"Forgiving"},"3":{"en":"Petty"},"4":{"en":"Generous"}},"answer":"3","solution":{"en":"<b>Magnanimous (उदार) = generous and forgiving, especially toward a rival.</b><br><b>Noble (महान)</b> = morally admirable<br><b>Forgiving (क्षमाशील)</b> = ready to pardon<br><b>Petty (छोटी सोच वाला)</b> = small-minded and mean ✔<br><b>Generous (उदार)</b> = willing to give<br>More antonyms: mean-spirited, spiteful, uncharitable.<br><br><b>Hence, the correct answer is option (3): Petty.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":86,"local_id":"50086","quid":"Q1000072566","section":"ENGLISH","topic":"Spelling Check","question":{"en":"Spot the correct spelling of a phase-change term for absorbing moisture from air. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Deliquescence"},"2":{"en":"Deliquesence"},"3":{"en":"Deliquessence"},"4":{"en":"Deliquescense"}},"answer":"1","solution":{"en":"<b>Deliquescence (द्रवीभवन) = absorption of atmospheric moisture until a substance dissolves.</b><br>The correct spelling is “deliquescence.”<br><b>Deliquesence</b> omits “c” before “e”; <b>Deliquessence</b> doubles “s.”<br><b>Deliquescense</b> replaces the second “c” with “s.”<br><br><b>Hence, the correct answer is option (1): Deliquescence.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":87,"local_id":"50087","quid":"Q1000072567","section":"ENGLISH","topic":"Spelling Check","question":{"en":"Identify the misspelt word. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Reprihensible"},"2":{"en":"Idiosyncratic"},"3":{"en":"Obstreperous"},"4":{"en":"Lamentable"}},"answer":"1","solution":{"en":"<b>Reprehensible (निंदनीय) = deserving condemnation.</b><br><b>Reprihensible</b> uses “i” instead of “e” after “repr.”<br><b>Idiosyncratic (विशिष्ट)</b> = peculiar to an individual; spelling correct.<br><b>Obstreperous (उपद्रवी)</b> = unruly; <b>lamentable (दुःखद)</b> = regrettable.<br><br><b>Hence, the correct answer is option (1): Reprihensible.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":88,"local_id":"50088","quid":"Q1000072568","section":"ENGLISH","topic":"One Word Substitution","question":{"en":"Choose the correct one-word substitution for: “A person who hates mankind”. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Misanthrope"},"2":{"en":"Pessimist"},"3":{"en":"Skeptic"},"4":{"en":"Misogynist"}},"answer":"1","solution":{"en":"<b>Misanthrope (मानव-द्वेषी) = a person who hates humanity.</b><br><b>Pessimist (निराशावादी)</b> = someone who expects bad outcomes<br><b>Skeptic (संशयवादी)</b> = someone who doubts accepted beliefs<br><b>Misogynist (स्त्री-द्वेषी)</b> = a person who hates women<br><br><b>Hence, the correct answer is option (1): Misanthrope.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":89,"local_id":"50089","quid":"Q1000072569","section":"ENGLISH","topic":"One Word Substitution","question":{"en":"Choose the correct one-word substitute for: “The invention or use of new words or expressions.” [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Neology"},"2":{"en":"Neologism"},"3":{"en":"Coinage"},"4":{"en":"Jargon"}},"answer":"2","solution":{"en":"<b>Neologism (नवशब्द-प्रयोग) = a newly coined word or expression, or its use.</b><br><b>Neology (नवशब्द-विषय)</b> = the study or practice of new words<br><b>Coinage (शब्द-गढ़न)</b> = the invention of words<br><b>Jargon (तकनीकी शब्दावली)</b> = specialized language<br>“Neologism” best fits the stated concept.<br><br><b>Hence, the correct answer is option (2): Neologism.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":90,"local_id":"50090","quid":"Q1000072570","section":"ENGLISH","topic":"Spotting Errors","question":{"en":"Find the part of the sentence that contains an error:<br>The economic indicators, though initially showing signs of recovery, (1)/ were eventually deemed insufficiently compelling (2)/ to warrant an upward revision of interest rates (3)/ by most analysts who had doubted its trajectory. (4) [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"(1)"},"2":{"en":"(2)"},"3":{"en":"(3)"},"4":{"en":"(4)"}},"answer":"4","solution":{"en":"<b>Rule: The plural antecedent “indicators” requires “their,” not “its.”</b><br>Part (4) should read “who had doubted <b>their</b> trajectory.”<br>The pronoun must agree with the plural economic indicators.<br>The other parts are correct.<br><br><b>Hence, the correct answer is option (4): (4).</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":91,"local_id":"50091","quid":"Q1000072571","section":"ENGLISH","topic":"Homophones and Homonyms","question":{"en":"Select the sentence containing the homonym of the highlighted word:<br>The choir sang a <b>motet</b> written for Advent. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"The motet featured complex polyphonic layering."},"2":{"en":"The musicologist analyzed a 14th-century motet."},"3":{"en":"The legal clerk filed a motet to the high court."},"4":{"en":"The cathedral’s motet was accompanied by lute."}},"answer":"3","solution":{"en":"<b>Motet = a sacred choral composition.</b><br>The original sentence and options A, B and D use this musical meaning.<br>Option C places “motet” in a legal filing, indicating a different referent and likely confusion with “motion.”<br>Therefore, C is the intended homonymous use.<br><br><b>Hence, the correct answer is option (3): The legal clerk filed a motet to the high court.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":92,"local_id":"50092","quid":"Q1000072572","section":"ENGLISH","topic":"Sentence Improvement","question":{"en":"Choose the most suitable option to replace the highlighted part of the sentence:<br>He was <b>accused for</b> stealing money. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"accused to"},"2":{"en":"accused of"},"3":{"en":"accused about"},"4":{"en":"accused by"}},"answer":"2","solution":{"en":"<b>Rule: “Accused of + gerund” is the standard construction.</b><br>Correct sentence: “He was <b>accused of</b> stealing money.”<br>“To,” “about” and “by” do not introduce the alleged offence in this pattern.<br>The preposition “of” is required.<br><br><b>Hence, the correct answer is option (2): accused of.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":93,"local_id":"50093","quid":"Q1000072573","section":"ENGLISH","topic":"Sentence Improvement","question":{"en":"Choose the most suitable option to replace the highlighted part of the sentence:<br>They reached the station <b>in time</b> to catch the train. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"just in time to catch the train"},"2":{"en":"at the time to catch the train"},"3":{"en":"on time for catching the train"},"4":{"en":"timely to catch the train"}},"answer":"1","solution":{"en":"<b>“Just in time” emphasizes arrival immediately before it would have been too late.</b><br>Correct sentence: “They reached the station <b>just in time to catch the train</b>.”<br>“At the time” and “timely” are unidiomatic here.<br>“On time” means punctual but lacks the emphatic narrow escape.<br><br><b>Hence, the correct answer is option (1): just in time to catch the train.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":94,"local_id":"50094","quid":"Q1000072574","section":"ENGLISH","topic":"Direct Indirect (Narration)","question":{"en":"A sentence is provided in indirect speech. From the four given options, choose the one that most accurately conveys the sentence in its corresponding direct speech.<br>The neurologist speculated that the patient might have regained partial synaptic plasticity had the therapy commenced earlier. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"The neurologist speculated, “The patient might regain partial synaptic plasticity if therapy commenced earlier.”"},"2":{"en":"The neurologist speculated, “Had the therapy commenced earlier, the patient might have regained partial synaptic plasticity.”"},"3":{"en":"The neurologist speculated, “If therapy was commenced earlier, plasticity might regain.”"},"4":{"en":"The neurologist speculated, “If therapy had commenced earlier, the patient might regain synaptic plasticity.”"}},"answer":"2","solution":{"en":"<b>Rule: Restore the inverted unreal-past condition without changing its modal perfect result.</b><br>“Had the therapy commenced earlier” is correct inversion.<br>A and D change “might have regained” to “might regain.”<br>C uses incorrect tense and omits the patient as subject.<br><br><b>Hence, the correct answer is option (2): The neurologist speculated, “Had the therapy commenced earlier, the patient might have regained partial synaptic plasticity.”.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":95,"local_id":"50095","quid":"Q1000072575","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Rearrange the following sentences to form a meaningful passage:<br>1. Augmented reality (AR) enhances user interaction by overlaying digital elements onto the physical world.<br>2. It has applications in gaming, education, and training.<br>3. AR uses devices like smartphones and AR glasses to deliver experiences.<br>4. However, widespread adoption is limited due to the cost of AR hardware. [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"2-4-1-3"},"2":{"en":"3-2-1-4"},"3":{"en":"4-1-3-2"},"4":{"en":"1-3-2-4"}},"answer":"4","solution":{"en":"<b>Order: 1-3-2-4</b><br>Sentence 1 defines AR, and sentence 3 explains the devices used to deliver it.<br>Sentence 2 gives its applications.<br>Sentence 4 concludes with the cost barrier to widespread adoption.<br><br><b>Hence, the correct answer is option (4): 1-3-2-4.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":96,"local_id":"50096","quid":"Q1000072576","section":"ENGLISH","topic":"Cloze Test","question":{"en":"The spread of misinformation in the digital age has made critical thinking more (1)___ than ever before. Without the ability to (2)___ facts from falsehoods, citizens cannot make informed decisions about public affairs or hold their elected representatives accountable. Political leaders who rely on emotional (3)___ rather than rational argument may succeed in the short term, but they gradually erode the quality of public discourse and weaken democratic institutions. Educational systems must therefore (4)___ analytical skills in students from the earliest stages of their schooling. A democracy deprived of critical thinkers becomes progressively (5)___ to manipulation and division, ultimately threatening the very foundations of free and fair governance.<br><br><br>(1) [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Optional"},"2":{"en":"Trivial"},"3":{"en":"Imperative"},"4":{"en":"Redundant"}},"answer":"3","solution":{"en":"<b>Imperative (अत्यावश्यक) = absolutely necessary.</b><br>Misinformation makes critical thinking more imperative than ever.<br><b>Optional (वैकल्पिक)</b> = not required<br><b>Trivial (तुच्छ)</b> = unimportant; <b>redundant (अनावश्यक)</b> = unnecessary<br><br><b>Hence, the correct answer is option (3): Imperative.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":97,"local_id":"50097","quid":"Q1000072577","section":"ENGLISH","topic":"Cloze Test","question":{"en":"The spread of misinformation in the digital age has made critical thinking more (1)___ than ever before. Without the ability to (2)___ facts from falsehoods, citizens cannot make informed decisions about public affairs or hold their elected representatives accountable. Political leaders who rely on emotional (3)___ rather than rational argument may succeed in the short term, but they gradually erode the quality of public discourse and weaken democratic institutions. Educational systems must therefore (4)___ analytical skills in students from the earliest stages of their schooling. A democracy deprived of critical thinkers becomes progressively (5)___ to manipulation and division, ultimately threatening the very foundations of free and fair governance.<br><br><br>(2) [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Discern"},"2":{"en":"Conceal"},"3":{"en":"Embellish"},"4":{"en":"Dismiss"}},"answer":"1","solution":{"en":"<b>Discern (पहचानना, अंतर करना) = recognize or distinguish.</b><br>Citizens must discern facts from falsehoods.<br><b>Conceal (छिपाना)</b> = hide<br><b>Embellish (सजाना)</b> = decorate or exaggerate; <b>dismiss (खारिज करना)</b> = reject<br><br><b>Hence, the correct answer is option (1): Discern.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":98,"local_id":"50098","quid":"Q1000072578","section":"ENGLISH","topic":"Cloze Test","question":{"en":"The spread of misinformation in the digital age has made critical thinking more (1)___ than ever before. Without the ability to (2)___ facts from falsehoods, citizens cannot make informed decisions about public affairs or hold their elected representatives accountable. Political leaders who rely on emotional (3)___ rather than rational argument may succeed in the short term, but they gradually erode the quality of public discourse and weaken democratic institutions. Educational systems must therefore (4)___ analytical skills in students from the earliest stages of their schooling. A democracy deprived of critical thinkers becomes progressively (5)___ to manipulation and division, ultimately threatening the very foundations of free and fair governance.<br><br><br>(3) [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Empathy"},"2":{"en":"Guidance"},"3":{"en":"Restraint"},"4":{"en":"Rhetoric"}},"answer":"4","solution":{"en":"<b>Rhetoric (वाक्चातुर्य) = language designed to persuade.</b><br>“Emotional rhetoric” contrasts with rational argument.<br><b>Empathy (सहानुभूति)</b> = understanding others’ feelings<br><b>Guidance (मार्गदर्शन)</b> = advice; <b>restraint (संयम)</b> = self-control<br><br><b>Hence, the correct answer is option (4): Rhetoric.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":99,"local_id":"50099","quid":"Q1000072579","section":"ENGLISH","topic":"Cloze Test","question":{"en":"The spread of misinformation in the digital age has made critical thinking more (1)___ than ever before. Without the ability to (2)___ facts from falsehoods, citizens cannot make informed decisions about public affairs or hold their elected representatives accountable. Political leaders who rely on emotional (3)___ rather than rational argument may succeed in the short term, but they gradually erode the quality of public discourse and weaken democratic institutions. Educational systems must therefore (4)___ analytical skills in students from the earliest stages of their schooling. A democracy deprived of critical thinkers becomes progressively (5)___ to manipulation and division, ultimately threatening the very foundations of free and fair governance.<br><br><br>(4) [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"Suppress"},"2":{"en":"Cultivate"},"3":{"en":"Simplify"},"4":{"en":"Eliminate"}},"answer":"2","solution":{"en":"<b>Cultivate (विकसित करना) = develop a skill through education and practice.</b><br>Schools must cultivate analytical skills from an early stage.<br><b>Suppress (दबाना)</b> = restrain<br><b>Simplify (सरल करना)</b> = make easier; <b>eliminate (समाप्त करना)</b> = remove<br><br><b>Hence, the correct answer is option (2): Cultivate.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":100,"local_id":"50100","quid":"Q1000072580","section":"ENGLISH","topic":"Cloze Test","question":{"en":"The spread of misinformation in the digital age has made critical thinking more (1)___ than ever before. Without the ability to (2)___ facts from falsehoods, citizens cannot make informed decisions about public affairs or hold their elected representatives accountable. Political leaders who rely on emotional (3)___ rather than rational argument may succeed in the short term, but they gradually erode the quality of public discourse and weaken democratic institutions. Educational systems must therefore (4)___ analytical skills in students from the earliest stages of their schooling. A democracy deprived of critical thinkers becomes progressively (5)___ to manipulation and division, ultimately threatening the very foundations of free and fair governance.<br><br><br>(5) [SSC CGL 14/10/26 Shift 3]"},"options":{"1":{"en":"immune"},"2":{"en":"Indifferent"},"3":{"en":"Vulnerable"},"4":{"en":"Resilient"}},"answer":"3","solution":{"en":"<b>Vulnerable (संवेदनशील) = easily harmed or exploited.</b><br>A democracy without critical thinkers becomes vulnerable to manipulation.<br><b>Immune (सुरक्षित)</b> = protected<br><b>Indifferent (उदासीन)</b> = unconcerned; <b>resilient (लचीला)</b> = able to recover<br><br><b>Hence, the correct answer is option (3): Vulnerable.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false}]}}};